    def _apply_lottie_to_hero(self, hero_view, asset_path):
        if not asset_path or hero_view is None:
            return False
        try:
            File = jclass("java.io.File")
            RLottieDrawable = jclass("org.telegram.ui.Components.RLottieDrawable")
            drawable = RLottieDrawable(File(asset_path), "pepe_supporter_push", AndroidUtilities.dp(88), AndroidUtilities.dp(88), None, False)
            
            def _apply_rec(v):
                if v is None: return False
                applied = False
                try:
                    v.clearColorFilter()
                    v.setAnimation(drawable)
                    v.setAutoRepeat(True)
                    v.playAnimation()
                    applied = True
                except Exception:
                    pass
                if not applied:
                    try:
                        v.setImageDrawable(drawable)
                        applied = True
                    except Exception:
                        pass
                try:
                    count = int(v.getChildCount())
                    for i in range(count):
                        if _apply_rec(v.getChildAt(i)):
                            applied = True
                except Exception:
                    pass
                return applied

            return _apply_rec(hero_view)
        except Exception as e:
            self.log("[support-popup] apply_lottie_to_hero error: " + _cause(e))
            return False

    def _support_feature_row(self, ctx, icon, title, subtitle, onClick=None):
        row = LinearLayout(ctx)
        row.setOrientation(LinearLayout.HORIZONTAL)
        row.setGravity(Gravity.CENTER_VERTICAL)
        row.setPadding(AndroidUtilities.dp(10), AndroidUtilities.dp(10),
                       AndroidUtilities.dp(10), AndroidUtilities.dp(10))

        if onClick is not None:
            try:
                row.setClickable(True)
                row.setFocusable(True)
                bg = GradientDrawable()
                bg.setCornerRadius(float(AndroidUtilities.dp(10)))
                bg.setColor(0x00000000)
                row.setBackground(self._ripple_bg(bg, self._theme_color("key_listSelector", 0x1A000000)))
                row.setOnClickListener(self._click(onClick))
            except Exception:
                pass

        mark = TextView(ctx)
        mark.setText(str(icon))
        mark.setGravity(Gravity.CENTER)
        mark.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 22)
        row.addView(mark, LinearLayout.LayoutParams(AndroidUtilities.dp(40), AndroidUtilities.dp(40)))

        texts = LinearLayout(ctx)
        texts.setOrientation(LinearLayout.VERTICAL)
        heading = TextView(ctx)
        heading.setText(str(title))
        heading.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
        try:
            heading.setTypeface(AndroidUtilities.bold())
            heading.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
        except Exception:
            pass
        body = TextView(ctx)
        body.setText(str(subtitle))
        body.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
        body.setLineSpacing(float(AndroidUtilities.dp(2)), 1.0)
        try:
            body.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
        except Exception:
            pass
        texts.addView(heading, LinearLayout.LayoutParams(-1, -2))
        lp_body = LinearLayout.LayoutParams(-1, -2); lp_body.topMargin = AndroidUtilities.dp(2)
        texts.addView(body, lp_body)
        lp_texts = LinearLayout.LayoutParams(0, -2, 1.0); lp_texts.leftMargin = AndroidUtilities.dp(10)
        row.addView(texts, lp_texts)

        if onClick is not None:
            arrow = TextView(ctx)
            arrow.setText("›")
            arrow.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 20)
            try:
                arrow.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            except Exception:
                pass
            row.addView(arrow, LinearLayout.LayoutParams(-2, -2))

        return row

