    def _customize_native_supporter_sheet(self, sheet, frag):
        """Rebrand exteraGram's real SupporterBottomSheet without rebuilding its UI."""
        try:
            base = sheet.getClass().getSuperclass()
            field = base.getDeclaredField("customView")
            field.setAccessible(True)
            scroll = field.get(sheet)
            root = scroll.getChildAt(0)

            ctx = frag.getParentActivity()
            res = ctx.getResources()
            package_name = ctx.getPackageName()

            self._apply_support_hero(root, ctx)

            try:
                root.getChildAt(1).setText(self.SUPPORT_TITLE)
                root.getChildAt(2).setText(self.SUPPORT_SUBTITLE)
            except Exception:
                pass

            def _open_bot_and_dismiss(_v=None):
                try:
                    if Browser is not None:
                        Browser.openUrl(ctx, CHIMERANFT_SUPPORT_URL)
                except Exception:
                    pass
                try:
                    sheet.dismiss()
                except Exception:
                    pass

            # A fourth perk row, built from the fork's OWN cell class, appended before the texts are
            # written — so the loop below styles all four rows in one pass and the perks read in the
            # right order (pay → badge → beta → bot). This customization runs several times per open
            # (exteraGram keeps re-applying its own strings), hence the «already a child» guard.
            try:
                beta_cell = getattr(self, "_beta_feature_cell", None)
                if beta_cell is None or int(root.indexOfChild(beta_cell)) < 0:
                    beta_cell = self._clone_native_feature_cell(
                        root.getChildAt(3), sheet, ctx, self.SUPPORT_ROW_ICONS[3],
                        self.SUPPORT_ROWS[3][0], self.SUPPORT_ROWS[3][1])
                    if beta_cell is not None:
                        lp_beta = LinearLayout.LayoutParams(-1, -2)
                        lp_beta.topMargin = AndroidUtilities.dp(16)
                        root.addView(beta_cell, 3 + len(self.SUPPORT_ROWS) - 1, lp_beta)
                        self._beta_feature_cell = beta_cell
            except Exception as beta_error:
                self.log("[support-popup] beta row: " + _cause(beta_error))

            for index, pair in enumerate(self.SUPPORT_ROWS):
                try:
                    cell = root.getChildAt(3 + index)
                    cell.getChildAt(1).setText(pair[0])
                    cell.getChildAt(2).setText(pair[1])
                    try:
                        for name in self.SUPPORT_ROW_ICONS[index]:
                            rid = int(res.getIdentifier(name, "drawable", package_name))
                            if rid != 0:
                                cell.getChildAt(0).setImageResource(rid)
                                break
                    except Exception:
                        pass
                    # Only the two rows that lead somewhere are tappable; a row that does nothing on
                    # touch but lights up like a button is the sloppy part of a sheet like this.
                    if index in self.SUPPORT_ROW_ACTIONS:
                        cell.setClickable(True)
                        cell.setOnClickListener(self._click(_open_bot_and_dismiss))
                    else:
                        cell.setClickable(False)
                except Exception:
                    pass

            # The action button used to be looked up at a fixed index — that index moves as soon as a
            # row is inserted above it, so find it by type instead.
            try:
                btn = None
                for index in range(int(root.getChildCount()) - 1, -1, -1):
                    child = root.getChildAt(index)
                    if "ButtonWithCounter" in str(child.getClass().getName()):
                        btn = child
                        break
                if btn is not None:
                    btn.setText("Купить", False)
                    btn.setOnClickListener(self._click(_open_bot_and_dismiss))
            except Exception:
                pass
            return root
        except Exception as e:
            self.log("[support-popup] native customize error: " + _cause(e))
            return None

    def _open_supporter_popup(self):
        """Open exteraGram's native supporter sheet (rebranded with Pepe Lottie) or custom fallback sheet."""
        try:
            frag = get_last_fragment() if get_last_fragment is not None else None
            if frag is None or frag.getParentActivity() is None:
                self._toast("Поддержка OpenChimeraNFT")
                return
            try:
                rp = frag.getResourceProvider()
            except Exception:
                rp = None

            opened = False
            try:
                NativeSheet = jclass("com.exteragram.messenger.components.SupporterBottomSheet")
                sheet = NativeSheet(frag, rp)
                
                # Apply custom branding IMMEDIATELY before showing to avoid text flash
                self._customize_native_supporter_sheet(sheet, frag)
                self._support_popup_sheet = sheet
                frag.showDialog(sheet)
                opened = True

                # Native sheet updates views/rates asynchronously; re-apply continuously at short delays
                # to prevent exteraGram from resetting the Pepe animation or texts.
                for delay in (0, 16, 50, 100, 200, 350, 500, 900):
                    try:
                        run_on_ui_thread(lambda s=sheet, f=frag: self._customize_native_supporter_sheet(s, f), delay)
                    except Exception:
                        pass
            except Exception as native_err:
                self.log("[support-popup] native sheet error, fallback to custom: " + _cause(native_err))

            if not opened:
                self._open_custom_supporter_sheet()
        except Exception as e:
            self.log("[support-popup] open error: " + _cause(e))
            self._toast("Не удалось открыть информацию о поддержке")

    # ---------------- bridge helpers ----------------
    # bridge calls that change the gift list → drop the cached getGiftDisplayJson result
    _GIFT_MUTATORS = frozenset(("updateGift", "updateGifts", "removeGift", "removeGifts", "craftGifts",
                                "addGift", "addGifts",
                                "replaceGift", "reloadAll", "importProfile", "setGiftVisibility",
                                "resetLocalProfile"))

    # Bridge calls that change something a settings row displays. Refreshing from here — rather
    # than from each of the two dozen call sites — is what keeps the screen honest when the state
    # is changed from somewhere else entirely (a gift's «Носить», a restored backup, a transfer).
    _SETTINGS_MUTATORS = frozenset(("setUsername", "setUsernameReplaceOriginal",
                                    "setNumber", "setRating", "setHideOfficialGifts",
                                    "setWearEnabled", "setSyncEnabled", "setSmoothMode",
                                    "setShowUnavailableGifts", "setLocalPremium", "setVisualBalances",
                                    "setMarketSpendEnabled",
                                    "setPinnedChannel", "setVerificationMode", "setOptimization",
                                    "importProfile", "reloadAll", "addGift", "addGifts",
                                    "removeGift", "removeGifts", "replaceGift", "craftGifts",
                                    "resetLocalProfile"))

    def _jvoid(self, method, sig=(), args=()):
        """Call a static bridge method. sig items: 'int'|'long'|'str'. Returns the String/primitive result or None."""
        try:
            clazz = self._clazz
            if clazz is None:
                return None
            # getMethod is a reflective scan over the core class on EVERY bridge call —
            # cache the resolved Method per (name, sig); the hot UI paths (settings,
            # gift grid) hit the same few methods repeatedly.
            mcache = getattr(self, "_jm_cache", None)
            if mcache is None:
                mcache = {}
                self._jm_cache = mcache
            m = mcache.get((method, sig))
            if m is None:
                # [bridge-fix] lazy type resolution: a bridge call can run before the
                # preload window has filled the globals (early hook / settings render).
                # getMethod then received null Classes and threw 'parameter type is
                # null' — and the WRITE was silently dropped.
                global _STR_CLS, _INT_T, _LONG_T
                if _STR_CLS is None:
                    try: _STR_CLS = JavaClass.forName("java.lang.String")
                    except Exception: pass
                if _INT_T is None:
                    try: _INT_T = JInteger.TYPE
                    except Exception: pass
                if _LONG_T is None:
                    try: _LONG_T = JLong.TYPE
                    except Exception: pass
                tmap = {"int": _INT_T, "long": _LONG_T, "str": _STR_CLS}
                _types = []
                for _t in sig:
                    _tc = tmap.get(_t)
                    if _tc is None:
                        raise RuntimeError("bridge type %r unresolved" % (_t,))
                    _types.append(_tc)
                m = clazz.getMethod(method, *_types)
                mcache[(method, sig)] = m
            jargs = []
            for t, a in zip(sig, args):
                if t == "int":
                    jargs.append(JInteger(int(a)))
                elif t == "long":
                    jargs.append(JLong(int(a)))
                else:
                    jargs.append("" if a is None else str(a))
            res = m.invoke(None, *jargs)
            if method in ("addGifts", "mergeState", "updateGifts", "updateGift",
                          "removeGifts", "removeGift", "replaceGift", "craftGifts",
                          "deliverGiftBatch", "pushSyncNow", "reloadAll"):
                _diag("[bridge] " + method + " -> " + str(res)[:200])
            if method in self._GIFT_MUTATORS:
                self._gifts_cache = None
                self._upg_match_cache = {}
            if method in self._SETTINGS_MUTATORS:
                self._schedule_settings_refresh()
            return res
        except Exception as e:
            try:
                # [bridge-fix] log each DISTINCT (method, sig) failure once — a core
                # without a method (isOptimizationEnabled in this fork) spammed the log
                # on every settings render while None was the safe answer anyway.
                if "NoSuchMethodException" in _cause(e):
                    _miss = getattr(self, "_jm_missing", None)
                    if _miss is None:
                        _miss = set()
                        self._jm_missing = _miss
                    if (method, sig) in _miss:
                        return None
                    _miss.add((method, sig))
                self.log("OpenChimeraNFT bridge " + method + " err: " + _cause(e))
            except Exception:
                pass
            return None

    def _core_reveal_sent(self, b64, dialog_id, comment=""):
        """[market-visual] Draw the gift message in the chat via the core.

        deliverGiftBatch only QUEUES outbox events; the visual gift message used
        to be produced by the sync round-trip (server merge -> poll ->
        applyTransfer -> GiftReveal). With the author server dead that chain
        never fired: the cart closed, the toast said the gifts were on their
        way, and nothing appeared anywhere. The core already carries the whole
        local renderer - GiftReveal.showSent, the same method the native gift
        sheet drives (b64 -> TL_messageActionStarGift service message ->
        MessagesStorage.putMessages + MessagesController.updateInterfaceWithMessages
        + confetti) - so drive it directly, once per delivered row.
        """
        try:
            if not b64 or jclass is None:
                return False
            main_cls = JavaClass.forName("com.chimeranft.core.Main")
            main_inst = main_cls.getMethod("getInstance").invoke(None)
            if main_inst is None:
                _diag("[reveal] core Main not initialized")
                return False
            reveal = main_cls.getMethod(
                "access$getGiftReveal$p", main_cls).invoke(None, main_inst)
            if reveal is None:
                _diag("[reveal] core reveal is null")
                return False
            from java.lang import Boolean as JBoolean
            m = reveal.getClass().getMethod(
                "showSent", JavaClass.forName("java.lang.String"), JLong.TYPE,
                JavaClass.forName("java.lang.String"),
                JBoolean.TYPE, JBoolean.TYPE)
            m.invoke(reveal, str(b64), JLong(int(dialog_id)),
                     "" if comment is None else str(comment),
                     JBoolean(True), JBoolean(True))
            return True
        except Exception as e:
            try: _diag("[reveal] showSent err: " + _cause(e))
            except Exception: pass
            return False

    @staticmethod
    def _bridge_ok(raw):
        """Did a bridge WRITE actually happen? Returns ``(ok, text)``.

        The idiom this replaces — ``value = str(self._jvoid(...) or ""); ok = "FAIL" not in value``
        — reports success for every way a bridge call can fail without raising: the loaded core does
        not have that method (``_jvoid`` logs and returns None), the core never initialized (it
        answers the literal ``"(not initialized)"``), or the write was blocked. ``"FAIL" not in ""``
        is True, so the plugin said «Канал закреплён в профиле» and stored nothing — the button
        looked dead because the only honest signal, the unchanged card, was the quiet one.
        """
        if raw is None:
            return False, ""
        text = str(raw).strip()
        if not text:
            return False, ""
        low = text.lower()
        for marker in ("fail", "fatal", "not initialized", "blocked", "exception"):
            if marker in low:
                return False, text
        return True, text

    def _settings(self):
        """Current Java state as a dict (one bridge read)."""
        try:
            raw = self._jvoid("getSettingsJson")
            return json.loads(str(raw)) if raw else {}
        except Exception:
            return {}

    # ---- keep the host's Switch preferences equal to the core's real state --------------------
    #
    # A Switch row is NOT rendered from the `default=` we pass. The host stores its value in its
    # own preferences and reads it back with getPluginSettingBoolean(pluginId, key, default), so
    # `default` only ever decides what the row shows the very first time. Every OTHER way the same
    # state changes — the Username/Number dialog, «Носить» on a gift, a restored .profile, an
    # incoming transfer, switching Telegram account — writes the core's Store and leaves that
    # preference alone. That is why turning Username off elsewhere left the settings screen still
    # claiming it was on. Mirroring the core into those keys removes the second source of truth.
    _SWITCH_MIRROR = (
        ("chimeranft_sync_enabled", "sync_enabled", True),
        ("chimeranft_smooth_mode", "smooth_mode", True),
        ("chimeranft_hide_official_gifts_local", "hide_official_gifts", False),
        ("chimeranft_username_enabled", "username_enabled", False),
        ("chimeranft_number_enabled", "number_enabled", False),
    )

    _OPTIMIZATION_MIRROR = (
        ("chimeranft_opt_dormant", "dormant"),
        ("chimeranft_opt_unhookfling", "unhookFling"),
        ("chimeranft_opt_emojifreeze", "emojiFreeze"),
    )

    @staticmethod
    def _as_bool(value, default=False):
        """The host hands preferences back as Boolean, but a legacy entry can arrive as a String;
        `bool("false")` is True, so never trust the raw value."""
        if value is None:
            return bool(default)
        if isinstance(value, bool):
            return value
        text = str(value).strip().lower()
        if text in ("true", "1", "yes", "on"):
            return True
        if text in ("false", "0", "no", "off", ""):
            return False
        return bool(default)

    def _mirror_switch(self, key, value, default=False):
        try:
            if self._as_bool(self.get_setting(key, default), default) != bool(value):
                self.set_setting(key, bool(value), False)
        except Exception:
            pass

    def _sync_settings_switches(self, st=None):
        """Push the core's authoritative state into the host's Switch preferences.

        Returns the settings dict it used, so callers that were going to read it anyway pay for
        exactly one bridge call."""
        try:
            state = self._settings() if st is None else st
        except Exception:
            return st or {}
        if getattr(self, "set_setting", None) is None or getattr(self, "get_setting", None) is None:
            return state
        # The list builder and the host's fillItems run back to back; a human cannot change state
        # between them, so a short window keeps one screen build to one mirroring pass.
        try:
            import time as _t
            now = _t.time()
            if now - float(getattr(self, "_switch_mirror_at", 0.0)) < 0.25:
                return state
            self._switch_mirror_at = now
        except Exception:
            pass
        # Writing a preference makes the host reload the settings list, which re-enters
        # create_settings() and therefore this method. The second pass finds every value already
        # equal and writes nothing, so it terminates either way — but a plain re-entrancy flag
        # says so outright instead of relying on that.
        if getattr(self, "_mirroring_switches", False):
            return state
        self._mirroring_switches = True
        try:
            for key, field, default in self._SWITCH_MIRROR:
                self._mirror_switch(key, state.get(field, default), default)
            # The rating row calls itself «shown» only when it is enabled AND has points.
            try:
                rating = (bool(state.get("rating_enabled", False))
                          and int(state.get("rating_value", 0) or 0) > 0)
            except Exception:
                rating = False
            self._mirror_switch("chimeranft_rating_enabled", rating, False)
            # Scroll accelerations live in the core's live flags, not in Store.
            for key, option in self._OPTIMIZATION_MIRROR:
                self._mirror_switch(key, self._opt_on(option), True)
        finally:
            self._mirroring_switches = False
        return state

    def _plugin_id(self):
        """The id the host filed this plugin under (Elyx meta.yml id, not our module id)."""
        pid = getattr(self, "_plugin_settings_id", "")
        if pid:
            return pid
        for attr in ("id", "plugin_id", "_id"):
            try:
                value = getattr(self, attr, None)
                if value:
                    self._plugin_settings_id = str(value)
                    return self._plugin_settings_id
            except Exception:
                pass
        try:
            controller = jclass("com.exteragram.messenger.plugins.PluginsController").getInstance()
            keys = controller.getPlugins().keySet().iterator()
            while keys.hasNext():
                key = str(keys.next() or "")
                if _is_our_id(key):
                    self._plugin_settings_id = key
                    return key
        except Exception:
            pass
        return __id__

    def _schedule_settings_refresh(self):
        """Coalesced rebuild of the cached settings rows after a state change.

        The host builds the root list ONCE (create_settings) and caches it, so a subtext like
        «Premium · Username · Number» keeps whatever it said when the screen was first opened.
        Asking the host to reload the list re-runs create_settings() and posts its own
        pluginSettingsRegistered, which repaints an open screen and costs nothing when none is."""
        try:
            import threading, time as _t
            now = _t.time()
            if now - float(getattr(self, "_settings_refresh_at", 0.0)) < 0.25:
                return
            self._settings_refresh_at = now
            timer = threading.Timer(0.30, self._refresh_settings_rows)
            timer.daemon = True
            timer.start()
        except Exception:
            self._refresh_settings_rows()

    def _refresh_settings_rows(self):
        try:
            self._switch_mirror_at = 0.0   # a real change just landed — never skip this pass
            self._sync_settings_switches()
        except Exception:
            pass
        try:
            controller = jclass("com.exteragram.messenger.plugins.PluginsController").getInstance()
            controller.loadPluginSettings(self._plugin_id())
        except Exception as e:
            try: self.log("[settings] rows refresh: " + _cause(e))
            except Exception: pass

    def _sync_status(self):
        try:
            raw = self._jvoid("getSyncStatusJson")
            return json.loads(str(raw)) if raw else {"state": "off", "enabled": False}
        except Exception:
            return {"state": "error", "enabled": False}

    def _sync_status_text(self, status=None):
        s = status or self._sync_status()
        if not bool(s.get("enabled", False)):
            return S("sync_status_off")
        state = str(s.get("state", "ready"))
        if state == "error":
            return S("sync_status_error")
        blocked = int(s.get("duplicates_blocked", 0) or 0)
        return S("sync_status_ok_blocked", blocked) if blocked else S("sync_status_ok")

    def _performance_mode(self):
        try:
            import time as _t
            cached = getattr(self, "_perf_mode_cache", None)
            if cached is not None and _t.time() - cached[0] < 3.0:
                return int(cached[1])
            raw_mode = self._jvoid("getPerformanceMode")
            mode = int(raw_mode) if raw_mode is not None else 1
            self._perf_mode_cache = (_t.time(), mode)
            return mode
        except Exception:
            return 1

    def _performance_status(self):
        try:
            raw = self._jvoid("getPerformanceStatusJson")
            return json.loads(str(raw)) if raw else {"mode": 1, "mode_name": "balanced"}
        except Exception:
            return {"mode": 1, "mode_name": "balanced"}

    def _smooth_mode_enabled(self):
        cached = getattr(self, "_smooth_mode_cached", None)
        if cached is not None:
            return bool(cached)
        try:
            cached = bool(self._settings().get("smooth_mode", True))
        except Exception:
            cached = True
        self._smooth_mode_cached = cached
        return cached

    def _performance_label(self, status=None):
        s = status or self._performance_status()
        mode = int(s.get("mode", 1) or 1)
        name = (S("perf_mode_quality") if mode == 0
                else (S("perf_mode_balance") if mode == 1 else S("perf_mode_economy")))
        return name + S("perf_auto_suffix")

    # ---------------- settings menu (1:1 layout, wired to the bridge) ----------------
    def create_settings(self):
        # exteraGram registers the plugin's settings (→ shows the ⚙️ gear in the list) ONLY
        # if create_settings() returns a NON-EMPTY list without throwing (PythonPluginsEngine
        # .loadPluginSettings: null/empty result → no gear). So build defensively + log, and
        # never return empty when the UI classes are available.
        try:
            items = self._build_settings()
            try: self.log("[settings] create_settings -> %d items" % (len(items) if items else 0))
            except Exception: pass
            if items:
                return items
        except Exception as e:
            try: self.log("[settings] create_settings ERROR: " + _cause(e))
            except Exception: pass
        if Text is None:
            return []
        # fallback: a single valid row guarantees the gear appears even if the rich build failed
        try:
            return [Text(text="OpenChimeraNFT", subtext=S("menu_open_settings"),
                         icon="msg2_reactions2", on_click=lambda _: self._open_about())]
        except Exception:
            return []

    def _build_settings(self):
        if Text is None:
            return []
        # Mirror first: the host reads each Switch row's value from its own preferences right after
        # this list is handed back, so this is the last moment at which the two can be aligned.
        st = self._sync_settings_switches()
        return [
            self._menu_header("OpenChimeraNFT"),
            Text(text=S("menu_gifts"), subtext=self._gifts_subtext(st),
                 icon="msg_emoji_gem", on_click=self._tapped("select", self._open_my_gifts),
                 link_alias="gifts"),
            Text(text=S("menu_profile"), subtext=self._profile_summary(st),
                 icon="msg_settings_solar", create_sub_fragment=self._sub_profile,
                 link_alias="profile"),
            Text(text=S("menu_premium"),
                 subtext=(S("menu_premium_on") if bool(st.get("local_premium", False))
                          else S("menu_premium_off")),
                 icon="msg_gift_premium_solar",
                 on_click=lambda view: self._toggle_local_premium_with_ripple(view),
                 link_alias="premium"),
            Text(text=S("menu_balance"),
                 subtext=self._visual_balance_summary(st),
                 icon="msg_payment_card_solar",
                 on_click=self._tapped("coin", self._open_visual_balance_dialog),
                 link_alias="balance"),
            self._menu_header(S("menu_extra_header")),
            Text(text=S("menu_backup"), subtext=self._backup_subtext(st),
                 icon="msg_share",
                 create_sub_fragment=self._sub_data, link_alias="backup"),
            # «Плавность» (frame-budget switches + hook diagnostics) is deliberately NOT in this
            # list: it is a developer instrument, not a user setting, and the owner asked for it out
            # of the menu. _sub_performance() is kept — it is the only way to read pollHooks() /
            # OpenTrace / UiGuard on a real device — so restoring access is one row, not a rewrite.
            Text(text=S("menu_help"), subtext=S("menu_help_sub"),
                 icon="msg_info", on_click=self._tapped("open", self._open_help_carousel),
                 link_alias="help"),
            Text(text=S("menu_support_author"), subtext=S("menu_support_author_sub"),
                 icon="msg_fave",
                 on_click=self._tapped("heartbeat", self._open_supporter_deeplink),
                 link_alias="support_author"),
            # About AND the changelog: one row, one sheet. Nothing here opens by itself any
            # more — this row is the only way to the changelog.
            Text(text=S("menu_about"), subtext=S("menu_about_sub", _LOADER_VERSION),
                 icon="msg2_reactions2",
                 on_click=self._tapped("open", self._open_about), link_alias="about"),
            Text(text="Диагностика",
                 subtext="скопировать лог сохранения в буфер обмена",
                 icon="msg_info",
                 on_click=self._tapped("open", self._copy_diag_log),
                 link_alias="diag"),
            # «Исходный код» — the repo lives on GitHub; the runtime settings
            # screen already carries the same button, the native screen did not.
            Text(text="Исходный код",
                 subtext="GitHub — m4rker20-rgb/OpenChimeraNFT",
                 icon="msg_share",
                 on_click=self._tapped("open", self._open_source_page),
                 link_alias="src"),
        ]

    def _open_source_page(self):
        """«Исходный код» — open the GitHub repo (in-app browser, clipboard fallback)."""
        url = "https://github.com/m4rker20-rgb/OpenChimeraNFT"
        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is not None:
                Browser = jclass("org.telegram.messenger.browser.Browser")
                if Browser is not None:
                    Browser.openUrl(ctx, url)
                    return
        except Exception:
            pass
        try:
            AndroidUtilities.addToClipboard(url)
            self._toast("Ссылка скопирована: " + url)
        except Exception:
            self._toast(url)

    def _copy_diag_log(self):
        try:
            p = os.path.join(_resolve_data_dir(), "diag.log")
            raw = ""
            if os.path.exists(p):
                with open(p, "r", encoding="utf-8", errors="replace") as fh:
                    raw = fh.read()
            tail = raw.splitlines()[-400:]
            text = "\n".join(tail) if tail else "(лог пуст)"
            try:
                AndroidUtilities.addToClipboard(text)
            except Exception:
                try:
                    from android.content import ClipData as _ClipData
                    from android.content import Context as _Context
                    _cm = ApplicationLoader.applicationContext.getSystemService(
                        _Context.CLIPBOARD_SERVICE)
                    _cm.setPrimaryClip(_ClipData.newPlainText("diag", text))
                except Exception:
                    pass
            self._toast("Диагностика: скопировано %d строк" % len(tail))
            _diag("diag copied to clipboard (%d lines)" % len(tail))
        except Exception as e:
            self._toast("Диагностика: " + _cause(e))

    def _tapped(self, name, fn):
        """Adapt a no-argument action to Elyx's settings-row callback.

        Routine navigation must stay silent.  The sole exception is an immediate destructive
        action: clearing a whole saved identity list has no later callback in which to report the
        outcome, so it gets one compact destructive pulse.
        """
        def _run(view=None):
            if name == "crunch":
                self._hap("crunch", view, essential=True)
            return fn()
        return _run

    def _toggled(self, fn):
        """Adapt a settings switch without adding feedback on top of the host control."""
        def _run(value):
            return fn(bool(value))
        return _run

    def _menu_header(self, text):
        try:
            if Header is not None:
                return Header(text=str(text))
        except Exception:
            pass
        return Divider(text=str(text))

    def _visual_balance_summary(self, st=None):
        s = st or self._settings()
        if not bool(s.get("visual_balance_configured", False)):
            return S("balance_setup")
        return S("balance_summary", str(s.get("visual_stars", "0")), str(s.get("visual_grams", "0")))

    def _open_visual_balance_dialog(self):
        try:
            fragment = get_last_fragment()
            ctx = fragment.getParentActivity() if fragment else None
            if ctx is None:
                self._toast(S("no_context"))
                return
            run_on_ui_thread(lambda: self._show_balance_sheet(ctx))
        except Exception as error:
            self.log("[visual-balance] open: " + _cause(error))

    #: Quick steps under each field. Setting a visual balance is picking a round number, not
    #: doing arithmetic, so the taps are worth more than the keyboard here.
    _STAR_STEPS = (100, 1000, 10000)
    _GRAM_STEPS = (1, 10, 100)

    def _show_balance_sheet(self, ctx):
        """Stars and GRAM in one sheet, each with what it is worth.

        The old dialog was two bare number fields with no sense of scale — «7.25 GRAM» says
        nothing until you know what a GRAM is. GRAM *is* TON, so its fiat line uses the same
        live `ton_usd_rate` as the Fragment price editor, and Stars uses the same per-star
        rate the gift constructor values gifts with. Both are local and visual: a purchase
        deducts them, nothing leaves the device.
        """
        try:
            self._drop_balance_sheet_refs()
            self._balance_ctx = ctx
            st = self._settings()
            rate = self._ton_usd_rate()
            accent = self._theme_color("key_featuredStickers_addButton", 0xFF3390EC)
            grey = self._theme_color("key_windowBackgroundWhiteGrayText", 0xFF9AA3AE)
            ink = self._theme_color("key_dialogTextBlack", 0xFFFFFFFF)

            scroll = ScrollView(ctx)
            scroll.setVerticalScrollBarEnabled(False)
            col = LinearLayout(ctx)
            col.setOrientation(LinearLayout.VERTICAL)
            col.setPadding(AndroidUtilities.dp(16), AndroidUtilities.dp(14),
                           AndroidUtilities.dp(16), AndroidUtilities.dp(18))

            header = LinearLayout(ctx)
            header.setOrientation(LinearLayout.HORIZONTAL)
            header.setGravity(Gravity.CENTER_VERTICAL)
            titles = LinearLayout(ctx)
            titles.setOrientation(LinearLayout.VERTICAL)
            title = TextView(ctx)
            title.setText("Баланс")
            title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 20)
            title.setTextColor(ink)
            try: title.setTypeface(AndroidUtilities.bold())
            except Exception: pass
            titles.addView(title, LinearLayout.LayoutParams(-1, -2))
            subtitle = TextView(ctx)
            subtitle.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
            subtitle.setTextColor(accent)
            titles.addView(subtitle, LinearLayout.LayoutParams(-1, -2))
            header.addView(titles, LinearLayout.LayoutParams(0, -2, 1.0))
            header.addView(self._tg_icon_button(
                ctx, ("ic_close_white", "msg_close", "msg_clear"), grey, "Закрыть",
                lambda v: self._close_balance_sheet()),
                LinearLayout.LayoutParams(AndroidUtilities.dp(40), AndroidUtilities.dp(40)))
            hlp = LinearLayout.LayoutParams(-1, -2); hlp.bottomMargin = AndroidUtilities.dp(12)
            col.addView(header, hlp)

            fields = {}

            def _amount_card(icon_names, icon_tint, unit, value, steps, on_change):
                """One currency: icon, big editable amount, unit, its worth, quick steps."""
                card = LinearLayout(ctx)
                card.setOrientation(LinearLayout.VERTICAL)
                try:
                    shape = GradientDrawable()
                    shape.setCornerRadius(float(AndroidUtilities.dp(14)))
                    shape.setColor(self._theme_color("key_windowBackgroundGray", 0xFF1B2732))
                    card.setBackground(shape)
                except Exception:
                    pass
                card.setPadding(AndroidUtilities.dp(14), AndroidUtilities.dp(10),
                                AndroidUtilities.dp(14), AndroidUtilities.dp(12))
                row = LinearLayout(ctx)
                row.setOrientation(LinearLayout.HORIZONTAL)
                row.setGravity(Gravity.CENTER_VERTICAL)
                mark = ImageView(ctx)
                self._set_tg_icon(mark, icon_names, icon_tint, unit)
                mlp = LinearLayout.LayoutParams(AndroidUtilities.dp(22), AndroidUtilities.dp(22))
                mlp.rightMargin = AndroidUtilities.dp(8)
                row.addView(mark, mlp)
                field = EditText(ctx)
                field.setSingleLine(True)
                field.setInputType(8194)          # NUMBER | DECIMAL
                field.setText(str(value or "0"))
                field.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 22)
                field.setBackground(None)
                try:
                    field.setTextColor(ink)
                    field.setHintTextColor(grey)
                    field.setTypeface(AndroidUtilities.bold())
                except Exception:
                    pass
                row.addView(field, LinearLayout.LayoutParams(0, -2, 1.0))
                unit_view = TextView(ctx)
                unit_view.setText(unit)
                unit_view.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
                unit_view.setTextColor(grey)
                row.addView(unit_view, LinearLayout.LayoutParams(-2, -2))
                card.addView(row, LinearLayout.LayoutParams(-1, -2))

                worth = TextView(ctx)
                worth.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
                worth.setTextColor(grey)
                wlp = LinearLayout.LayoutParams(-1, -2); wlp.topMargin = AndroidUtilities.dp(2)
                card.addView(worth, wlp)

                chips = LinearLayout(ctx)
                chips.setOrientation(LinearLayout.HORIZONTAL)
                for step in steps:
                    chip = TextView(ctx)
                    chip.setText("+" + _fmt_amount(step, 0))
                    chip.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
                    chip.setGravity(Gravity.CENTER)
                    chip.setPadding(AndroidUtilities.dp(12), 0, AndroidUtilities.dp(12), 0)
                    chip.setTextColor(accent)
                    try:
                        shape = GradientDrawable()
                        shape.setCornerRadius(float(AndroidUtilities.dp(15)))
                        shape.setColor(self._col(0x223390EC))
                        chip.setBackground(self._ripple_bg(shape, accent))
                    except Exception:
                        pass
                    chip.setOnClickListener(self._click(
                        lambda v, f=field, s=step: _bump(f, s)))
                    clp = LinearLayout.LayoutParams(-2, AndroidUtilities.dp(30))
                    clp.rightMargin = AndroidUtilities.dp(6)
                    chips.addView(chip, clp)
                reset = TextView(ctx)
                reset.setText("0")
                reset.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
                reset.setGravity(Gravity.CENTER)
                reset.setPadding(AndroidUtilities.dp(14), 0, AndroidUtilities.dp(14), 0)
                reset.setTextColor(grey)
                try:
                    shape = GradientDrawable()
                    shape.setCornerRadius(float(AndroidUtilities.dp(15)))
                    shape.setColor(self._theme_color("key_windowBackgroundGray", 0xFF20242A))
                    reset.setBackground(self._ripple_bg(shape, accent))
                except Exception:
                    pass
                reset.setOnClickListener(self._click(lambda v, f=field: _set_field(f, 0.0)))
                chips.addView(reset, LinearLayout.LayoutParams(-2, AndroidUtilities.dp(30)))
                cclp = LinearLayout.LayoutParams(-1, -2); cclp.topMargin = AndroidUtilities.dp(10)
                card.addView(chips, cclp)

                # The whole card is the control: the field is a thin strip between the icon,
                # the unit label and the padding.
                card.setOnClickListener(self._click(
                    lambda v, f=field: self._focus_field(f), feedback=False))
                field.setOnClickListener(self._click(
                    lambda v, f=field: self._focus_field(f), feedback=False))
                fields[unit] = (field, worth, on_change)
                return card

            def _set_field(field, value):
                try:
                    field.setText(_fmt_amount(value, 4))
                    field.setSelection(len(str(field.getText() or "")))
                except Exception:
                    pass
                _repaint()

            def _bump(field, step):
                current = _parse_amount(field.getText()) or 0.0
                _set_field(field, current + float(step))

            def _repaint():
                try:
                    stars_field = fields.get("Stars")
                    gram_field = fields.get("GRAM")
                    stars_value = _parse_amount(stars_field[0].getText()) if stars_field else None
                    gram_value = _parse_amount(gram_field[0].getText()) if gram_field else None
                    if stars_field is not None:
                        usd = (stars_value or 0.0) * self._STAR_USD
                        stars_field[1].setText(("≈ $%s" % _fmt_amount(usd)) if stars_value
                                               else "Звёзды не начислены")
                    if gram_field is not None:
                        usd = _fiat_for_ton(gram_value, rate, "USD")
                        gram_field[1].setText(("≈ $%s · курс %s $/TON"
                                               % (_fmt_amount(usd), _fmt_amount(rate, 3)))
                                              if gram_value else "GRAM не начислены")
                    parts = []
                    if stars_value:
                        parts.append("%s Stars" % _fmt_amount(stars_value, 4))
                    if gram_value:
                        parts.append("%s GRAM" % _fmt_amount(gram_value, 4))
                    subtitle.setText(" · ".join(parts) if parts else "пусто — задай значения")
                except Exception as error:
                    self.log("[visual-balance] repaint: " + _cause(error))

            stars_card = _amount_card(("star", "msg_premium_liststar", "settings_stars"),
                                      accent, "Stars", st.get("visual_stars", "0"),
                                      self._STAR_STEPS, _repaint)
            col.addView(stars_card, LinearLayout.LayoutParams(-1, -2))
            gram_card = _amount_card(("msg_ton",), self._col(self._TON_BLUE), "GRAM",
                                     st.get("visual_grams", "0"), self._GRAM_STEPS, _repaint)
            gclp = LinearLayout.LayoutParams(-1, -2); gclp.topMargin = AndroidUtilities.dp(10)
            col.addView(gram_card, gclp)

            proxies = []
            try:
                _TW = jclass("android.text.TextWatcher")

                class _BalanceWatcher(dynamic_proxy(_TW)):
                    def beforeTextChanged(self2, s, start, count, after): pass
                    def onTextChanged(self2, s, start, before, count):
                        try: _repaint()
                        except Exception: pass
                    def afterTextChanged(self2, editable): pass

                for unit in ("Stars", "GRAM"):
                    entry = fields.get(unit)
                    if entry is None:
                        continue
                    watcher = _BalanceWatcher()
                    proxies.append(watcher)
                    entry[0].addTextChangedListener(watcher)
            except Exception as error:
                self.log("[visual-balance] watcher: " + _cause(error))
            self._balance_proxies = proxies
            _repaint()

            hint = TextView(ctx)
            hint.setText("Баланс локальный: он виден только на этом устройстве, "
                         "а визуальные покупки списывают его сами.")
            hint.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 12)
            hint.setTextColor(grey)
            hnlp = LinearLayout.LayoutParams(-1, -2); hnlp.topMargin = AndroidUtilities.dp(12)
            col.addView(hint, hnlp)

            # «Тратить звёзды в маркете» — ON deducts the balance on a market buy, OFF keeps the buy
            # but leaves the balance frozen. Read the live state so the switch opens as it is stored;
            # the write goes straight to the Store bridge (GiftHook reads it on the next purchase).
            try:
                TextCheckCell = jclass("org.telegram.ui.Cells.TextCheckCell")
                # `raw or "1"` was the bug: the bridge answers with a java.lang.Integer, and 0 is
                # FALSY in Python, so a stored OFF read back as "1". The switch then opened checked
                # while the store said off — «выключатель включён, а звёзды не тратятся» — and every
                # tap on it wrote off again (nv = not isChecked()), so the state could never recover.
                raw_spend = self._jvoid("isMarketSpendEnabled")
                if raw_spend is None:
                    spend_on = bool(st.get("market_spend_enabled", True))
                else:
                    spend_on = str(raw_spend).strip().lower() not in ("0", "false")
                spend_cell = TextCheckCell(ctx, 21, True)
                spend_cell.setTextAndValueAndCheck(
                    S("balance_spend_toggle"), S("balance_spend_toggle_sub"), bool(spend_on), True, False)

                def _toggle_spend(_v, _cell=spend_cell):
                    nv = not bool(_cell.isChecked())
                    _cell.setChecked(nv)
                    self._hap_toggle(nv)
                    self._jvoid("setMarketSpendEnabled", ("int",), (1 if nv else 0,))

                spend_cell.setOnClickListener(self._click(_toggle_spend))
                sclp = LinearLayout.LayoutParams(-1, -2); sclp.topMargin = AndroidUtilities.dp(6)
                sclp.leftMargin = sclp.rightMargin = -AndroidUtilities.dp(16)  # cell has its own padding
                col.addView(spend_cell, sclp)
            except Exception as error:
                self.log("[visual-balance] spend toggle: " + _cause(error))

            def _save():
                stars_entry = fields.get("Stars")
                gram_entry = fields.get("GRAM")
                stars_text = str(stars_entry[0].getText()) if stars_entry else "0"
                gram_text = str(gram_entry[0].getText()) if gram_entry else "0"
                # _bridge_ok, not `"FAIL" not in str(... or "")`: a core that did not answer at all
                # would otherwise close the sheet on «Баланс обновлён» without writing anything.
                written, result = self._bridge_ok(self._jvoid(
                    "setVisualBalances", ("str", "str"), (stars_text or "0", gram_text or "0")))
                if not written:
                    self._hap("error")
                    self._toast("Проверь значения баланса" if result else "Ядро не ответило")
                    return
                self._hap("coin")
                self._toast("Баланс обновлён")
                self._close_balance_sheet()

            save_btn = jclass("org.telegram.ui.Stories.recorder.ButtonWithCounterView")(ctx, True, None)
            save_btn.setRound()
            save_btn.setText("Сохранить", False)
            save_btn.setOnClickListener(self._click(lambda v: _save()))
            self._apply_channel_button_press_scale(save_btn)
            sblp = LinearLayout.LayoutParams(-1, AndroidUtilities.dp(48))
            sblp.topMargin = AndroidUtilities.dp(14)
            col.addView(save_btn, sblp)

            scroll.addView(col)
            screen_h = 0
            try:
                screen_h = int(AndroidUtilities.displaySize.y)
            except Exception:
                screen_h = 0
            max_h = int(screen_h * 0.82) if screen_h > 0 else AndroidUtilities.dp(600)
            estimate = AndroidUtilities.dp(470)
            holder = FrameLayout(ctx)
            holder.addView(scroll, FrameLayout.LayoutParams(
                -1, max_h if estimate > max_h else -2))
            sheet = BottomSheet.Builder(ctx).setCustomView(holder).create()
            self._balance_sheet = sheet
            try: sheet.setCanDismissWithSwipe(False)
            except Exception: pass
            # Without this the window keeps FLAG_ALT_FOCUSABLE_IM and neither amount field
            # can open the keyboard.
            try: sheet.setFocusable(True)
            except Exception as error: self.log("[visual-balance] focusable: " + _cause(error))
            plugin = self
            this_sheet = sheet

            class _BalanceDismissed(dynamic_proxy(jclass("android.content.DialogInterface$OnDismissListener"))):
                def onDismiss(self2, _dialog):
                    cur = getattr(plugin, "_balance_sheet", None)
                    if cur is not None and not cur.equals(this_sheet):
                        return
                    plugin._drop_balance_sheet_refs()

            listener = _BalanceDismissed()
            self._balance_dismiss = listener
            try: sheet.setOnDismissListener(listener)
            except Exception: pass
            self._show_sheet_animated(sheet, holder)
        except Exception as error:
            self.log("[visual-balance] sheet: " + _cause(error))
            self._toast("Не удалось открыть баланс")

    def _focus_field(self, field):
        """Focus an EditText and raise the keyboard — the tap target is the whole card."""
        try:
            field.requestFocus()
            try:
                field.setSelection(len(str(field.getText() or "")))
            except Exception:
                pass
            AndroidUtilities.showKeyboard(field)
        except Exception as error:
            self.log("[sheet] keyboard: " + _cause(error))

    def _close_balance_sheet(self):
        sheet = getattr(self, "_balance_sheet", None)
        if sheet is not None:
            try: sheet.dismiss()
            except Exception: pass

    def _drop_balance_sheet_refs(self):
        self._balance_sheet = None
        self._balance_ctx = None
        self._balance_proxies = None
        self._balance_dismiss = None

    # The "?" row and its explanation dialog are gone. It was the only caller of the dialog, and
    # the row itself carried no label — a settings row whose entire text is a question mark tells
    # the user nothing about what tapping it does. Explanations live where they are already asked
    # for: «Помощь» in the root menu and the per-row subtext, which states the live value.

    def _sub_sync(self, parent_view=None):
        st = self._sync_settings_switches()
        ss = self._sync_status()
        return [
            self._menu_header(S("sync_header")),
            Switch(key="chimeranft_sync_enabled", text=S("sync_toggle"),
                   subtext=self._sync_status_text(ss), default=bool(st.get("sync_enabled", True)),
                   icon="msg_retry", on_change=lambda v: self._set_sync_enabled(bool(v))),
            Text(text=S("sync_now"), subtext=S("sync_now_sub"),
                 icon="msg_retry", on_click=lambda _: self._sync_now()),
            Text(text=S("sync_state"),
                 subtext=S("sync_state_sub", int(ss.get("cache_users", 0) or 0),
                           int(ss.get("duplicates_blocked", 0) or 0)),
                 icon="msg_stats_solar", on_click=self._tapped("select", self._show_sync_diagnostics)),
        ]

    def _backup_subtext(self, st):
        try:
            count = int(st.get("auto_backup_count", 0) or 0)
            ts = int(st.get("auto_backup_time", 0) or 0)
            when = ""
            if ts > 0:
                import datetime
                when = datetime.datetime.fromtimestamp(ts).strftime("%H:%M")
            return S("backup_count_at", count, when) if when else S("backup_count", count)
        except Exception:
            return S("backup_none")

    def _profile_summary(self, st):
        parts = []
        if bool(st.get("local_premium", False)): parts.append("Premium")
        if bool(st.get("username_enabled", False)): parts.append(S("profile_username"))
        if bool(st.get("number_enabled", False)): parts.append(S("profile_number"))
        if bool(st.get("rating_enabled", False)): parts.append(S("profile_rating"))
        return " · ".join(parts) if parts else S("profile_not_set")

    def _sub_performance(self, parent_view=None):
        st = self._sync_settings_switches()
        ps = self._performance_status()
        avg = float(ps.get("average_frame_ms", 0) or 0)
        jank = float(ps.get("jank_percent", 0) or 0)
        return [
            self._menu_header(S("perf_header")),
            Switch(key="chimeranft_smooth_mode", text=S("perf_smooth"),
                   subtext=S("perf_smooth_sub"),
                   default=bool(st.get("smooth_mode", True)), icon="msg_stats_solar",
                   on_change=lambda v: self._set_smooth_mode(bool(v))),
            Text(text=S("perf_auto"), subtext=self._performance_label(ps), icon="msg_retry"),
            Text(text=S("perf_last"), subtext=S("perf_last_sub", "%.1f" % avg, "%.1f" % jank),
                 icon="msg_stats_solar"),
            Divider(text=S("perf_note")),

            self._menu_header(S("speedups_header")),
            Switch(key="chimeranft_opt_dormant", text=S("opt_dormant"),
                   subtext=S("opt_dormant_sub"),
                   default=self._opt_on("dormant"), icon="msg_channel",
                   on_change=lambda v: self._set_optimization("dormant", v)),
            Switch(key="chimeranft_opt_unhookfling", text=S("opt_unhookfling"),
                   subtext=S("opt_unhookfling_sub"),
                   default=self._opt_on("unhookFling"), icon="msg_retry",
                   on_change=lambda v: self._set_optimization("unhookFling", v)),
            Switch(key="chimeranft_opt_emojifreeze", text=S("opt_emojifreeze"),
                   subtext=S("opt_emojifreeze_sub"),
                   default=self._opt_on("emojiFreeze"), icon="msg2_reactions2",
                   on_change=lambda v: self._set_optimization("emojiFreeze", v)),
            Text(text=S("diag_hooks"), subtext=S("diag_hooks_sub"),
                 icon="msg_stats_solar", on_click=self._tapped("select", self._show_hook_diagnostics)),
            Text(text=S("diag_order"),
                 subtext=S("diag_order_sub"),
                 icon="tabs_reorder", on_click=self._tapped("select", self._show_order_diag)),
            # A row that can switch a live hook off mid-scroll should not feel like the two above.
            Text(text=S("hook_killswitch"), subtext=S("hook_killswitch_sub"),
                 icon="msg_delete", on_click=self._tapped("warning", self._open_hook_killswitch_dialog)),
            Divider(text=S("speedups_note")),
        ]

    # ---- hook instrumentation (per-hook counters + live kill switches) ----

    _HOOK_GROUPS = ("getUser", "getUserFull", "getChat", "getChatFull", "chatCell",
                    "emojiFreeze", "botVerifIcon", "dialogCell", "exteraBadge",
                    "exteraSource", "putUser", "scrollState", "chatActivity")

    def _opt_on(self, option):
        try:
            return bool(int(self._jvoid("isOptimizationEnabled", ("str",), (option,)) or 0))
        except Exception:
            return True

    def _set_optimization(self, option, enabled):
        result = self._jvoid("setOptimization", ("str", "int"), (option, 1 if enabled else 0))
        self._hap_toggle(enabled)
        self._toast(str(result or option))

    def _show_hook_diagnostics(self):
        raw = str(self._jvoid("pollHooks") or S("no_data"))
        # pollGifts() existed in the core and was reachable from nothing, so the counters that
        # answer «подарки не грузятся» — savedReq/self/wrapped/inserted, plus lastReq and the
        # labelled err= from every catch on the gift path — could not be read on a device at all.
        # Exactly the gap «Плавность» itself had before it was wired up.
        try:
            gifts = str(self._jvoid("pollGifts") or "").strip()
        except Exception:
            gifts = ""
        if gifts:
            raw = raw + "\n\nGIFTS\n" + gifts
        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or AlertDialogBuilder is None:
                self._toast(raw[:180]); return
            b = AlertDialogBuilder(ctx)
            b.set_title(S("diag_hooks"))
            b.set_message(raw)
            b.set_positive_button(S("hooks_reset_counters"),
                                  lambda d, w: self._toast(str(self._jvoid("resetHookMetrics") or "")))
            b.set_negative_button(S("close"), None)
            run_on_ui_thread(b.show)
        except Exception:
            self._toast(raw[:180])

    def _open_hook_killswitch_dialog(self):
        """One switch per hook group. Scroll a channel with a group off to feel whether it was
        the cause — no rebuild, no reinstall."""
        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or AlertDialogBuilder is None:
                self._toast(S("not_here")); return
            names = list(self._HOOK_GROUPS)
            labels = []
            for name in names:
                disabled = bool(int(self._jvoid("isHookDisabled", ("str",), (name,)) or 0))
                labels.append(("✖ " if disabled else "✔ ") + name)
            def _pick(dlg, idx):
                try: dlg.dismiss()
                except Exception: pass
                if idx < 0 or idx >= len(names):
                    self._hap("dismiss")
                    return
                self._toggle_hook(names[idx])
            b = AlertDialogBuilder(ctx)
            b.set_title(S("hooks_pick_title"))
            b.set_items(labels, _pick)
            b.set_negative_button(S("close"), None)
            run_on_ui_thread(b.show)
        except Exception as exc:
            self._toast(S("open_failed", exc))

    def _toggle_hook(self, group):
        disabled = bool(int(self._jvoid("isHookDisabled", ("str",), (group,)) or 0))
        result = self._jvoid("setHookDisabled", ("str", "int"), (group, 0 if disabled else 1))
        # `disabled` is the state we just left: re-enabling a hook is the "on" direction.
        self._hap_toggle(disabled)
        self._toast(str(result or group))

    def _set_smooth_mode(self, enabled):
        self._jvoid("setSmoothMode", ("int",), (1 if enabled else 0,))
        self._smooth_mode_cached = bool(enabled)
        self._hap_toggle(enabled)
        self._toast(S("perf_smooth_on_toast") if enabled else S("perf_smooth_off_toast"))

    def _set_sync_enabled(self, enabled):
        self._jvoid("setSyncEnabled", ("int",), (1 if enabled else 0,))
        self._hap_toggle(enabled)
        self._toast(S("sync_enabled_toast") if enabled else S("sync_disabled_toast"))

    def _sync_now(self):
        result = self._jvoid("pushSyncNow")
        self._hap("impact")
        self._toast(S("sync_queued_toast"))
        return result

    def _show_sync_diagnostics(self):
        raw = str(self._jvoid("pollSync") or S("no_data"))
        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or AlertDialogBuilder is None:
                self._toast(raw[:180]); return
            b = AlertDialogBuilder(ctx)
            b.set_title(S("sync_diag_title"))
            b.set_message(raw)
            b.set_positive_button(S("sync_diag_push"), lambda d, w: self._sync_now())
            b.set_negative_button(S("close"), None)
            run_on_ui_thread(b.show)
        except Exception:
            self._toast(raw[:180])

    # ---- Профиль ----
