    def _open_update_check(self):
        """«Обновления» card → check now and self-update. Resets the popup/install
        latches so it ALWAYS works even after the auto-popup was dismissed/minimized:
        - _upd_popup_active / _upd_dismissed_until: cleared so the forced sheet shows;
        - _plug_installed: cleared so «Обновить» can re-trigger the install (the guard
          otherwise no-ops a second attempt → «не отдаёт нормально»)."""
        self._toast("Проверяю обновления…")
        self._upd_popup_active = False
        self._upd_dismissed_until = 0
        self._plug_installed = False
        try:
            self._check_for_update(True)
        except Exception as e:
            self.log("[upd] manual: " + _cause(e))
            self._toast("Ошибка проверки обновлений")

    def _open_cache_cleanup(self):
        """Multi-toggle cache-cleanup sheet (ported from the regular OpenChimeraNFT plugin):
        Каталог/Временные/Ассеты ON by default; Экспорты/Локальный профиль/Удалить-всё OFF.
        «Удалить плагин и все файлы» auto-enables every other toggle."""
        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or BottomSheet is None:
                self._clear_plugin_cache(); return
            TextCheckCell = jclass("org.telegram.ui.Cells.TextCheckCell")
            sheet = BottomSheet(ctx, False)
            accent = int(self._theme_color("key_featuredStickers_addButton", 0xFF3390EC))

            root = LinearLayout(ctx); root.setOrientation(LinearLayout.VERTICAL)
            root.setPadding(AndroidUtilities.dp(20), AndroidUtilities.dp(18), AndroidUtilities.dp(20), AndroidUtilities.dp(14))

            title = TextView(ctx); title.setText("Очистка кэша")
            title.setTextColor(int(self._theme_color("key_dialogTextBlack", 0xFFFFFFFF)))
            try: title.setTypeface(AndroidUtilities.bold())
            except Exception: pass
            title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 20)
            root.addView(title, LinearLayout.LayoutParams(-1, -2))

            subtitle = TextView(ctx)
            subtitle.setText("Выбери, что удалить. Опасные данные профиля по умолчанию выключены.")
            subtitle.setTextColor(int(self._theme_color("key_windowBackgroundWhiteGrayText2", 0xFF9AA3AE)))
            subtitle.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
            lp_sub = LinearLayout.LayoutParams(-1, -2); lp_sub.topMargin = AndroidUtilities.dp(6)
            root.addView(subtitle, lp_sub)

            selected = {"catalog": True, "temp": True, "assets": True,
                        "profiles": False, "local_profile": False, "purge_plugin": False}
            defs = list(self._cache_cleanup_option_defs()) + [
                ("purge_plugin", "Удалить плагин и все файлы",
                 "Рантайм, кэш, .profile, настройки и локальные данные")]
            cells = LinearLayout(ctx); cells.setOrientation(LinearLayout.VERTICAL)
            lp_cells = LinearLayout.LayoutParams(-1, -2); lp_cells.topMargin = AndroidUtilities.dp(16)
            cells_by_key = {}

            for idx, (key, title_text, desc_text) in enumerate(defs):
                cell = TextCheckCell(ctx, 21, True)
                cell.setTextAndValueAndCheck(str(title_text), str(desc_text), bool(selected.get(key, False)), True, idx != len(defs) - 1)
                cells_by_key[key] = cell

                def _toggle(v, _cell=cell, _key=key):
                    nv = not bool(selected.get(_key, False))
                    selected[_key] = nv
                    # Arming «удалить плагин и все файлы» ticks every other row on at once, so it
                    # gets a warning rather than the ordinary toggle click.
                    if _key == "purge_plugin" and nv:
                        self._hap("warning")
                    else:
                        self._hap_toggle(nv)
                    try: _cell.setChecked(nv)
                    except Exception: pass
                    if _key == "purge_plugin" and nv:
                        for k2, c2 in list(cells_by_key.items()):
                            selected[k2] = True
                            try: c2.setChecked(True)
                            except Exception: pass

                cell.setOnClickListener(self._click(_toggle, hap=None))
                if key == "purge_plugin":
                    lpc = LinearLayout.LayoutParams(-1, -2); lpc.topMargin = AndroidUtilities.dp(10)
                    cells.addView(cell, lpc)
                else:
                    cells.addView(cell)
            root.addView(cells, lp_cells)

            buttons = LinearLayout(ctx); buttons.setOrientation(LinearLayout.HORIZONTAL)
            lp_buttons = LinearLayout.LayoutParams(-1, -2); lp_buttons.topMargin = AndroidUtilities.dp(16)

            cancel = TextView(ctx); cancel.setText("Отмена"); cancel.setGravity(Gravity.CENTER)
            try: cancel.setTypeface(AndroidUtilities.bold())
            except Exception: pass
            cancel.setTextColor(accent)
            cancel.setPadding(AndroidUtilities.dp(8), AndroidUtilities.dp(14), AndroidUtilities.dp(8), AndroidUtilities.dp(14))
            cancel.setOnClickListener(self._click(lambda v: sheet.dismiss(), hap="dismiss"))

            apply = TextView(ctx); apply.setText("Очистить"); apply.setGravity(Gravity.CENTER)
            try: apply.setTypeface(AndroidUtilities.bold())
            except Exception: pass
            apply.setTextColor(-1)
            try:
                bg = GradientDrawable(); bg.setCornerRadius(float(AndroidUtilities.dp(12))); bg.setColor(accent); apply.setBackground(self._ripple_bg(bg, accent))
                apply.setElevation(float(AndroidUtilities.dp(2)))
            except Exception: pass
            apply.setPadding(AndroidUtilities.dp(8), AndroidUtilities.dp(14), AndroidUtilities.dp(8), AndroidUtilities.dp(14))

            def _apply(v):
                keys = [k for k, _t, _d in defs if bool(selected.get(k, False))]
                if not keys:
                    self._hap("error")
                    self._toast("Выбери хотя бы один пункт"); return
                try: sheet.dismiss()
                except Exception: pass
                if "purge_plugin" in keys:
                    self._confirm_purge_plugin(ctx)
                else:
                    # The crunch lands in _clear_selected_cache, once it knows what really went.
                    self._clear_selected_cache(keys)
            apply.setOnClickListener(self._click(_apply, hap=None))

            buttons.addView(cancel, LinearLayout.LayoutParams(0, -2, 1.0))
            lp_apply = LinearLayout.LayoutParams(0, -2, 1.0); lp_apply.leftMargin = AndroidUtilities.dp(10)
            buttons.addView(apply, lp_apply)
            root.addView(buttons, lp_buttons)

            sheet.setCustomView(root)
            self._show_sheet_animated(sheet, root)
        except Exception as e:
            self.log("[cache] " + _cause(e))
            self._clear_plugin_cache()

    def _cache_cleanup_option_defs(self):
        return [
            ("catalog", "Каталог и цены", "Списки подарков, фильтры, floor-цены"),
            ("temp", "Временные файлы", ".tmp, .bak, .recover и служебные sidecar-файлы"),
            ("assets", "Ассеты и аватары", "Кэш картинок и about/support ассетов"),
            ("profiles", "Экспорты .profile", "Сохранённые конфиги из Downloads/OpenChimeraNFT"),
            ("local_profile", "Локальный профиль", "Подарки, username, number, rating и настройки профиля"),
        ]

    def _remove_path_quiet(self, path):
        import os, shutil
        try:
            if not path or not os.path.exists(path):
                return 0
            if os.path.isdir(path):
                shutil.rmtree(path, ignore_errors=True)
            else:
                os.remove(path)
            return 1
        except Exception:
            return 0

    def _clear_selected_cache(self, keys):
        import os
        keys = set(str(k) for k in (keys or []))
        ddir = _resolve_data_dir() or ""
        removed = 0
        if "catalog" in keys:
            try: self._cat_ctrl = None
            except Exception: pass
            for attr in ("_market_floor_cache", "_catalog_items_cache", "_catalog_base_list", "_catalog_load_requested"):
                try: setattr(self, attr, None)
                except Exception: pass
        if "temp" in keys and ddir and os.path.isdir(ddir):
            # NEVER delete stolen_cache*.bak / .recover: those are the recovery generations
            # Elyx Core's Store votes on at every cold start. Wiping them under a «Кэш» button
            # left a torn or stripped live file as the only copy — one bad write then looked
            # like a permanent data reset. Only genuinely disposable staging files go.
            try:
                for n in os.listdir(ddir):
                    low = n.lower()
                    if low.startswith("stolen_cache") and not low.endswith(".tmp"):
                        continue
                    if n.endswith((".tmp", ".bak", ".recover")):
                        removed += self._remove_path_quiet(os.path.join(ddir, n))
            except Exception: pass
        if "assets" in keys and ddir and os.path.isdir(ddir):
            try:
                for n in os.listdir(ddir):
                    low = n.lower()
                    if low.endswith((".svg", ".png", ".webp", ".jpg")) or "asset" in low or "avatar" in low:
                        removed += self._remove_path_quiet(os.path.join(ddir, n))
            except Exception: pass
        if "profiles" in keys:
            try:
                for pdir in self._profile_dirs():
                    if not os.path.isdir(pdir):
                        continue
                    for n in os.listdir(pdir):
                        if n.lower().endswith(".profile"):
                            removed += self._remove_path_quiet(os.path.join(pdir, n))
            except Exception: pass
        if "local_profile" in keys and ddir and os.path.isdir(ddir):
            # DANGER: wipes gifts/username/number/rating/settings (the Java cache file(s)).
            try:
                for n in os.listdir(ddir):
                    low = n.lower()
                    if low.startswith("stolen_cache") or low.endswith(".json"):
                        removed += self._remove_path_quiet(os.path.join(ddir, n))
            except Exception: pass
            self._hap("crunch", essential=True)
            self._toast("Локальный профиль очищен — перезапусти Telegram")
            return
        # «хруст» only when something was actually broken up; an empty cache is just a tick.
        if removed:
            self._hap("crunch", essential=True)
        self._toast("Кэш очищен ✓" if removed else "Кэш уже пуст")

    def _confirm_purge_plugin(self, ctx):
        try:
            if AlertDialogBuilder is None:
                self._purge_all_plugin_files(); return
            b = AlertDialogBuilder(ctx)
            b.set_title("Удалить плагин и все файлы?")
            b.set_message("Будут удалены рантайм, кэш, .profile, настройки и локальные данные, а также сам плагин. Действие необратимо.")
            b.set_positive_button("Удалить", lambda d, w: self._purge_all_plugin_files())
            b.set_negative_button("Отмена", lambda d, w: self._hap("dismiss"))
            run_on_ui_thread(b.show)
        except Exception as e:
            self.log("[cache] purge confirm: " + _cause(e))

    def _purge_all_plugin_files(self, silent=False):
        import os
        removed = 0
        targets = [_resolve_data_dir()]
        try:
            if get_plugins_dir is not None:
                targets.extend(_runtime_dir_candidates())
        except Exception:
            pass
        for p in targets:
            removed += self._remove_path_quiet(p)
        try:
            for pdir in self._profile_dirs():
                if not os.path.isdir(pdir):
                    continue
                for n in os.listdir(pdir):
                    if n.lower().endswith(".profile"):
                        removed += self._remove_path_quiet(os.path.join(pdir, n))
        except Exception: pass
        # the installed .plugin file itself. Resolved through the helper, not
        # getPluginPath(__id__): the host files us under meta.yml's id, which is not
        # __id__, and an install older than the rename is filed under an older id again.
        try:
            pp = self._access_host_plugin_path()
            if pp: removed += self._remove_path_quiet(str(pp))
        except Exception as e:
            self.log("[cache] purge path: " + _cause(e))
        if not silent:
            self._hap("crunch", essential=True)
            self._toast("Плагин и все файлы удалены — перезапусти Telegram")

    def _clear_plugin_cache(self):
        import os, shutil
        removed = 0
        try:
            for root in _runtime_dir_candidates():
                if os.path.isdir(root):
                    shutil.rmtree(root, ignore_errors=True); removed += 1
        except Exception:
            pass
        self._prod = None
        if removed:
            self._hap("crunch", essential=True)
        self._toast("Кэш очищен ✓" if removed else "Кэш уже пуст")

    def _about_avatar_drawable(self, user):
        if AvatarDrawable is None:
            return None
        try:
            if user is not None:
                return AvatarDrawable(user)
        except Exception:
            pass
        try:
            d = AvatarDrawable()
            try: d.setInfo(0, CHIMERANFT_ABOUT_USERNAME, "")
            except Exception: pass
            return d
        except Exception:
            return None

    def _bind_about_avatar(self, av, user):
        """Show the support user's profile photo (placeholder initials until loaded)."""
        if av is None:
            return
        drawable = self._about_avatar_drawable(user)
        try:
            if drawable is not None:
                av.setImageDrawable(drawable)
        except Exception:
            pass
        if user is not None:
            try:
                av.setForUserOrChat(user, drawable)
            except Exception:
                try: av.setForUserOrChat(user)
                except Exception: pass

    def _current_user(self):
        """The logged-in account's User object (its avatar is cached locally → loads instantly)."""
        acc = _selected_account()
        try:
            mc = jclass("org.telegram.messenger.MessagesController").getInstance(acc)
            uc = UserConfig.getInstance(acc)
            u = None
            try: u = mc.getUser(uc.getClientUserId())
            except Exception: u = None
            if u is None:
                try: u = uc.getCurrentUser()
                except Exception: u = None
            return u
        except Exception:
            return None

    def _show_about_sheet(self, ctx=None, expand_changelog=False):
        """«О плагине» — one sheet in two sections: what the plugin is (avatar,
        description, Поддержка) and, below a separator, the changelog folded into a
        plate that opens in place. `expand_changelog` starts it open, which is how the
        once-per-version auto-open and the row's own tap both arrive here."""
        try:
            if ctx is None:
                frag = get_last_fragment()
                ctx = frag.getParentActivity() if frag else None
            if ctx is None:
                try: ctx = ApplicationLoader.applicationContext
                except Exception: ctx = None
            if ctx is None or BottomSheet is None:
                self._toast("OpenChimeraNFT " + __version__)
                return
            sheet = BottomSheet(ctx, True)
            root = LinearLayout(ctx)
            root.setOrientation(LinearLayout.VERTICAL)
            root.setPadding(AndroidUtilities.dp(16), AndroidUtilities.dp(16), AndroidUtilities.dp(16), AndroidUtilities.dp(16))

            row = LinearLayout(ctx)
            row.setOrientation(LinearLayout.HORIZONTAL)
            row.setGravity(Gravity.CENTER_VERTICAL)
            av = BackupImageView(ctx)
            try: av.setRoundRadius(AndroidUtilities.dp(14))
            except Exception: pass
            # the user's OWN profile photo (cached locally → loads immediately)
            self._bind_about_avatar(av, self._current_user())
            # The only way back into the hook diagnostics now that «Плавность» is out of the menu.
            # Deliberately here and not on a menu row: rows already own long press (it yields the
            # deep link to that setting), and nobody long-presses their own avatar inside an About
            # sheet by accident. pollHooks() is the one instrument that answers «какой хук стоит
            # кадра» on a real device, and §11.16 is the record of what happens without it.
            self._attach_long_press(av, self._show_hook_diagnostics)
            row.addView(av, LinearLayout.LayoutParams(AndroidUtilities.dp(64), AndroidUtilities.dp(64)))
            desc = TextView(ctx)
            desc.setText(S("about_description", __version__))
            desc.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 14)
            try: desc.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            except Exception: pass
            lpd = LinearLayout.LayoutParams(0, -2, 1.0); lpd.leftMargin = AndroidUtilities.dp(12)
            row.addView(desc, lpd)
            root.addView(row, LinearLayout.LayoutParams(-1, -2))

            btn = TextView(ctx)
            btn.setText(S("about_support"))
            btn.setGravity(Gravity.CENTER)
            btn.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 16)
            try:
                btn.setTextColor(Theme.getColor(Theme.key_featuredStickers_buttonText))
                bbg = GradientDrawable(); bbg.setCornerRadius(float(AndroidUtilities.dp(12)))
                bbg.setColor(Theme.getColor(Theme.key_featuredStickers_addButton))
                btn.setBackground(self._ripple_bg(bbg, Theme.getColor(Theme.key_featuredStickers_addButton)))
                btn.setElevation(float(AndroidUtilities.dp(2)))
            except Exception:
                pass
            btn.setPadding(AndroidUtilities.dp(12), AndroidUtilities.dp(12), AndroidUtilities.dp(12), AndroidUtilities.dp(12))

            def _support(v):
                try:
                    if Browser is not None:
                        Browser.openUrl(v.getContext(), CHIMERANFT_SUPPORT_URL)
                except Exception:
                    pass
                try: sheet.dismiss()
                except Exception: pass
            btn.setOnClickListener(self._click(_support))
            lpb = LinearLayout.LayoutParams(-1, -2); lpb.topMargin = AndroidUtilities.dp(14)
            root.addView(btn, lpb)

            # Between «Поддержка» and the changelog: the one switch that controls the only sheet
            # this plugin still opens on its own.
            self._add_channel_reminder_row(ctx, root)

            # Second section. Skipped entirely when no version has text — an empty plate
            # that opens onto nothing is worse than no plate.
            if self._changelog_entries():
                self._add_changelog_section(ctx, root, expand=bool(expand_changelog))

            self._changelog_sheet = sheet
            sheet.setCustomView(root)
            self._show_sheet_animated(sheet, root)
        except Exception as e:
            self.log("[about] sheet: " + _cause(e))
            self._toast("OpenChimeraNFT " + __version__)

    def _add_channel_reminder_row(self, ctx, root):
        """«Напоминать о канале разработчика» — the switch that owns the subscribe prompt.

        ON (the default) means a non-subscriber sees the prompt once after every install or
        update. OFF means it never appears again, on any future update, until it is switched back
        on here — or until the plugin is removed, which takes its settings with it."""
        try:
            TextCheckCell = jclass("org.telegram.ui.Cells.TextCheckCell")
            cell = TextCheckCell(ctx, 21, True)
            cell.setTextAndValueAndCheck(
                S("channel_reminder_toggle"), S("channel_reminder_toggle_sub"),
                bool(self._developer_channel_reminder_enabled()), True, False)

            def _toggle(_v, _cell=cell):
                nv = not bool(_cell.isChecked())
                _cell.setChecked(nv)
                self._hap_toggle(nv)
                self._set_developer_channel_reminder(nv)

            cell.setOnClickListener(self._click(_toggle))
            lp = LinearLayout.LayoutParams(-1, -2)
            lp.topMargin = AndroidUtilities.dp(8)
            lp.leftMargin = lp.rightMargin = -AndroidUtilities.dp(16)   # the cell has its own padding
            root.addView(cell, lp)
        except Exception as error:
            self.log("[about] channel reminder row: " + _cause(error))

    def _add_changelog_section(self, ctx, root, expand=False):
        """Separator + a tappable «Что нового» plate whose body expands in place."""
        title_color = int(self._theme_color("key_windowBackgroundWhiteBlackText", 0xFFFFFFFF))
        sub_color = int(self._theme_color("key_windowBackgroundWhiteGrayText", 0xFF9AA3AE))
        accent = int(self._theme_color("key_featuredStickers_addButton", 0xFF3390EC))

        separator = View(ctx)
        try: separator.setBackgroundColor(int(self._theme_color("key_divider", sub_color)))
        except Exception: pass
        lp_sep = LinearLayout.LayoutParams(-1, max(1, AndroidUtilities.dp(1) // 2))
        lp_sep.topMargin = AndroidUtilities.dp(18)
        root.addView(separator, lp_sep)

        plate = LinearLayout(ctx)
        plate.setOrientation(LinearLayout.VERTICAL)
        lp_plate = LinearLayout.LayoutParams(-1, -2)
        lp_plate.topMargin = AndroidUtilities.dp(14)
        root.addView(plate, lp_plate)

        head = LinearLayout(ctx)
        head.setOrientation(LinearLayout.HORIZONTAL)
        head.setGravity(Gravity.CENTER_VERTICAL)
        head.setPadding(AndroidUtilities.dp(14), AndroidUtilities.dp(12),
                        AndroidUtilities.dp(14), AndroidUtilities.dp(12))
        try:
            plate_bg = self._create_round_rect(
                self._theme_color("key_dialogBackground", 0xFF1A1A1A), radius_dp=14)
            head.setBackground(self._ripple_bg(plate_bg, accent))
        except Exception:
            pass

        labels = LinearLayout(ctx)
        labels.setOrientation(LinearLayout.VERTICAL)
        head_title = TextView(ctx)
        head_title.setText(S("changelog_title"))
        head_title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
        head_title.setTextColor(title_color)
        try: head_title.setTypeface(AndroidUtilities.getTypeface("fonts/rmedium.ttf"))
        except Exception: pass
        labels.addView(head_title, LinearLayout.LayoutParams(-1, -2))
        head_sub = TextView(ctx)
        head_sub.setText(S("changelog_subtitle", self._changelog_entries()[0][0]))
        head_sub.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
        head_sub.setTextColor(sub_color)
        lp_head_sub = LinearLayout.LayoutParams(-1, -2)
        lp_head_sub.topMargin = AndroidUtilities.dp(1)
        labels.addView(head_sub, lp_head_sub)
        head.addView(labels, LinearLayout.LayoutParams(0, -2, 1.0))

        # A caret, not an icon name: this has to read the same on every fork's theme.
        caret = TextView(ctx)
        caret.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
        caret.setTextColor(accent)
        head.addView(caret, LinearLayout.LayoutParams(-2, -2))
        plate.addView(head, LinearLayout.LayoutParams(-1, -2))

        body = self._changelog_body_view(ctx, title_color, accent)
        lp_body = LinearLayout.LayoutParams(-1, -2)
        lp_body.topMargin = AndroidUtilities.dp(4)
        plate.addView(body, lp_body)

        state = {"open": bool(expand)}

        def _render():
            opened = bool(state["open"])
            caret.setText("▲" if opened else "▼")
            body.setVisibility(View.VISIBLE if opened else View.GONE)

        def _toggle(_view=None):
            state["open"] = not state["open"]
            _render()
            self._hap("reveal" if state["open"] else "select")

        head.setOnClickListener(self._click(_toggle, hap=None))
        _render()

    def _changelog_body_view(self, ctx, title_color, accent):
        """The bulleted history, newest version first, in its own scroller so a long
        history cannot push the rest of the sheet off screen."""
        body = LinearLayout(ctx)
        body.setOrientation(LinearLayout.VERTICAL)
        body.setPadding(AndroidUtilities.dp(14), AndroidUtilities.dp(4),
                        AndroidUtilities.dp(14), AndroidUtilities.dp(4))
        for index, (version, lines) in enumerate(self._changelog_entries()):
            if index > 0:
                header = TextView(ctx)
                header.setText(S("changelog_version", version))
                header.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 14)
                header.setTextColor(accent)
                try: header.setTypeface(AndroidUtilities.getTypeface("fonts/rmedium.ttf"))
                except Exception: pass
                lp_header = LinearLayout.LayoutParams(-1, -2)
                lp_header.topMargin = AndroidUtilities.dp(16)
                body.addView(header, lp_header)
            for line in lines:
                row = LinearLayout(ctx)
                row.setOrientation(LinearLayout.HORIZONTAL)
                bullet = TextView(ctx)
                bullet.setText("•")
                bullet.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
                bullet.setTextColor(accent)
                row.addView(bullet, LinearLayout.LayoutParams(AndroidUtilities.dp(16), -2))
                text = TextView(ctx)
                text.setText(str(line))
                text.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
                text.setTextColor(title_color)
                row.addView(text, LinearLayout.LayoutParams(0, -2, 1.0))
                lp_row = LinearLayout.LayoutParams(-1, -2)
                lp_row.topMargin = AndroidUtilities.dp(10)
                body.addView(row, lp_row)

        scroll = ScrollView(ctx)
        scroll.addView(body, FrameLayout.LayoutParams(-1, -2))

        # Adapt to the text — only a long history scrolls, and only up to the cap.
        def _cap():
            try:
                limit = AndroidUtilities.dp(280)
                if scroll.getHeight() > limit:
                    lp = scroll.getLayoutParams(); lp.height = limit
                    scroll.setLayoutParams(lp)
            except Exception:
                pass
        try: run_on_ui_thread(_cap, 60)
        except Exception: pass
        return scroll

