            try:
                top_title.setTypeface(AndroidUtilities.getTypeface("fonts/rmedium.ttf"))
                top_title.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlackText))
                close.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            except Exception: pass
            top.addView(top_title, LinearLayout.LayoutParams(0, AndroidUtilities.dp(48), 1.0))
            top.addView(close, LinearLayout.LayoutParams(AndroidUtilities.dp(48), AndroidUtilities.dp(48)))
            root.addView(top, LinearLayout.LayoutParams(-1, AndroidUtilities.dp(48)))

            hero = FrameLayout(ctx)
            hero_icon = TextView(ctx)
            hero_icon.setGravity(Gravity.CENTER)
