            try: gif_label.setTextColor(self._col(0xCCFFFFFF))
            except Exception: pass
            hero.addView(hero_icon, self._frame(hero_icon, -1, -1, Gravity.CENTER, 0, 0, 0, 0))
            hero.addView(gif_label, self._frame(gif_label, -1, 34, Gravity.BOTTOM | Gravity.CENTER_HORIZONTAL, 0, 0, 0, 10))
            lp_hero = LinearLayout.LayoutParams(-1, AndroidUtilities.dp(300)); lp_hero.topMargin = AndroidUtilities.dp(4)
            root.addView(hero, lp_hero)

            title = TextView(ctx)
            title.setGravity(Gravity.CENTER)
