                if getattr(self, "_upd_popup_active", False):
                    # self-heal: if the flag has been stuck >5 min (sheet leaked / never
                    # got an onDismiss), clear it so auto-popups resume instead of dying.
                    if _t.time() - getattr(self, "_upd_popup_active_ms", 0) < 300:
                        return  # a sheet is genuinely showing — don't stack
                    self._upd_popup_active = False
