            sheet = BottomSheet(ctx, True)
            root = LinearLayout(ctx)
            root.setOrientation(LinearLayout.VERTICAL)
            root.setPadding(AndroidUtilities.dp(20), AndroidUtilities.dp(20), AndroidUtilities.dp(20), AndroidUtilities.dp(14))

            hero = LinearLayout(ctx)
            hero.setOrientation(LinearLayout.HORIZONTAL)
            hero.setGravity(Gravity.CENTER_VERTICAL)
            iv = BackupImageView(ctx)
            try: iv.setRoundRadius(AndroidUtilities.dp(14))
            except Exception: pass
            self._load_welcome_sticker(iv, "72_72")
            hero.addView(iv, LinearLayout.LayoutParams(AndroidUtilities.dp(56), AndroidUtilities.dp(56)))
            htext = LinearLayout(ctx); htext.setOrientation(LinearLayout.VERTICAL)
