    def _catalog_pick(self, gift_id, base_gift=None, base_title=""):
        if gift_id <= 0:
            self._toast("нет id подарка")
            return
        self._ctor_edit_id = 0   # adding a NEW gift from the catalog
        try:
            if getattr(self, "_catalog_sheet", None) is not None:
                self._catalog_sheet.dismiss()
        except Exception:
            pass
        if base_gift is None:
            base_gift = self._find_base_gift(gift_id)
        title = str(base_title or "").strip()
        if not title and base_gift is not None:
            try:
                title = str(getattr(base_gift, "title", "") or "").strip()
            except Exception:
                title = ""
        title = title or "NFT"
        self._toast("загружаю атрибуты…")

        def _on(models, patterns, backdrops, raw):
            if raw is not None and int(getattr(raw, "size", lambda: 0)()) > 0:
                self._show_native_constructor(gift_id, title, 1, raw, base_gift=base_gift)
            elif (models or patterns or backdrops):
                self._show_constructor_grid(None, models, patterns, backdrops, base_gift_id=gift_id)
            else:
                self._attrs_failed(gift_id)
        self._fetch_upgrade_attrs(gift_id, _on)

    # ---- NFT constructor (pick Model/Symbol/Backdrop, build + serialize, save) ----
    def _attr_pools(self):
        """Collect unique model/pattern/backdrop attribute objects from the library."""
        models, patterns, backdrops = {}, {}, {}
        for g in self._gifts():
            try:
                gift = self._deserialize_gift(g.get("b64"))
                if gift is None:
                    continue
                attrs = getattr(gift, "attributes", None)
                if attrs is None:
                    continue
                for i in range(int(attrs.size())):
                    a = attrs.get(i)
                    if a is None:
                        continue
                    cls = str(a.getClass().getSimpleName()).lower()
                    name = str(getattr(a, "name", "") or "")
                    if not name:
                        continue
                    if "model" in cls:
                        models[name] = a
                    elif "backdrop" in cls:
                        backdrops[name] = a
                    elif "pattern" in cls or "symbol" in cls:
                        patterns[name] = a
            except Exception:
                continue
        return models, patterns, backdrops

    def _make_original_details(self, od):
        """Build a TL_starGiftAttributeOriginalDetails so the upgraded NFT shows the
        native «Подарок от X для Y, отправлен DATE с комментарием Z» row."""
        try:
            OD = None
            for cn in ("org.telegram.tgnet.tl.TL_stars$TL_starGiftAttributeOriginalDetails",
                       "org.telegram.tgnet.tl.TL_stars$starGiftAttributeOriginalDetails"):
                try:
                    OD = jclass(cn); break
                except Exception:
                    continue
            if OD is None:
                return None
            attr = OD()
            PeerUser = jclass("org.telegram.tgnet.TLRPC$TL_peerUser")
            flags = 0
            suid = int(od.get("sender_uid") or 0)
            if suid > 0:
                sp = PeerUser(); sp.user_id = suid
                self._jset(attr, "sender_id", sp)
                flags |= 1
            ruid = int(od.get("recipient_uid") or 0)
            if ruid > 0:
                rp = PeerUser(); rp.user_id = ruid
                self._jset(attr, "recipient_id", rp)
            self._jset(attr, "date", int(od.get("date_ts") or 0))
            cc = str(od.get("comment") or "").strip()
            if cc:
                TwE = jclass("org.telegram.tgnet.TLRPC$TL_textWithEntities")
                twe = TwE()
                self._jset(twe, "text", cc)
                try:
                    twe.entities = jclass("java.util.ArrayList")()
                except Exception:
                    pass
                self._jset(attr, "message", twe)
                flags |= 2
            self._jset(attr, "flags", flags)
            return attr
        except Exception as e:
            try: self.log("[upg] origDetails: " + _cause(e))
            except Exception: pass
            return None

    def _build_unique_gift(self, model_a, pattern_a, backdrop_a, title, num, base_gift_id=0, base_gift=None,
                           original_details=None, forced_uid=0, crafted=False):
        """Build a TL_starGiftUnique + TL_savedStarGift wrapper from chosen attrs.
        Returns (gift, saved, b64, name, slug, uid); b64 is '' on failure."""
        try:
            ArrayList = jclass("java.util.ArrayList")
            J = jclass("org.telegram.tgnet.tl.TL_stars$TL_starGiftUnique")
            gift = J()
            import random as _r
            uid = int(forced_uid or 0) or _r.randint(100000000, 999999999)
            try: gift.id = uid
            except Exception: pass
            try:
                if int(base_gift_id or 0) > 0:
                    gift.gift_id = int(base_gift_id)
            except Exception: pass
            try: gift.num = int(num or 1)
            except Exception: pass
            # name: explicit title → base gift title → model attribute name → "NFT"
            name = str(title or "").strip()
            if (not name or name == "NFT") and base_gift is not None:
                try:
                    name = str(getattr(base_gift, "title", "") or "").strip() or name
                except Exception:
                    pass
            if not name or name == "NFT":
                try:
                    nm = str(getattr(model_a, "name", "") or "").strip()
                    if nm:
                        name = nm
                except Exception:
                    pass
            if not name:
                name = "NFT"
            slug = name.replace(" ", "") + "-" + str(num)
            try: gift.title = name
            except Exception: pass
            try: gift.slug = slug
            except Exception: pass
            if crafted:
                try: self._jset(gift, "crafted", True)
                except Exception: pass
                try: self._jset(model_a, "crafted", True)
                except Exception: pass
            gift.attributes = ArrayList()
            if model_a is not None: gift.attributes.add(model_a)
            if pattern_a is not None: gift.attributes.add(pattern_a)
            if backdrop_a is not None: gift.attributes.add(backdrop_a)
            # original-details row («Подарок от X для Y … с комментарием») on upgrade
            if original_details:
                od = self._make_original_details(original_details)
                if od is not None:
                    gift.attributes.add(od)

            # copy the model sticker/document so the collectible renders, + availability
            try:
                doc = None
                if model_a is not None:
                    doc = getattr(model_a, "document", None) or getattr(model_a, "sticker", None)
                if doc is None and base_gift is not None:
                    doc = getattr(base_gift, "sticker", None) or getattr(base_gift, "document", None)
                if doc is not None:
                    self._jset(gift, "document", doc)
                    self._jset(gift, "sticker", doc)
            except Exception:
                pass
            if base_gift is None and int(base_gift_id or 0) > 0:
                base_gift = self._find_base_gift(base_gift_id)
            try:
                self._copy_availability(gift, base_gift, num)
            except Exception as e:
                self.log("[ctor] avail: " + _cause(e))

            Saved = jclass("org.telegram.tgnet.tl.TL_stars$TL_savedStarGift")
            saved = Saved()
            saved.gift = gift
            try: self._jset(saved, "saved_id", int(uid))
            except Exception: pass

            SD = jclass("org.telegram.tgnet.SerializedData")
            try:
                size = int(saved.getObjectSize())
            except Exception:
                size = 8192
            sd = SD(max(size, 256))
            saved.serializeToStream(sd)
            data = sd.toByteArray()
            raw = bytes((int(b) & 0xFF) for b in data)
            b64 = base64.b64encode(raw).decode("ascii")
            return gift, saved, b64, name, slug, uid
        except Exception as e:
            try: self.log("[ctor] build_unique err: " + repr(e))
            except Exception: pass
            return None, None, "", "", "", 0

    def _build_and_save(self, model_a, pattern_a, backdrop_a, title, num, base_gift_id=0, base_gift=None, value_config=None, edit_id=0):
        try:
            gift, saved, b64, name, slug, uid = self._build_unique_gift(
                model_a, pattern_a, backdrop_a, title, num, base_gift_id, base_gift)
            if not b64:
                self._toast("сборка не удалась")
                return False

            entry = {"b64": b64, "inject": True, "title": name,
                     "slug": slug, "num": int(num or 1), "unique_id": int(uid),
                     "base_gift_id": int(base_gift_id or 0), "gift_kind": "local_upgraded"}
            if value_config and str(value_config.get("amount", "") or "").strip():
                entry["value_config"] = {
                    "amount": str(value_config.get("amount", "")).strip(),
                    "currency": str(value_config.get("currency", "USD") or "USD").upper()}
            # EDIT mode: drop the ORIGINAL entry FIRST so the result is a modify, not a
            # duplicate (remove-first is robust even if ids collide). edit_id = the gift's
            # unique_id/saved_id captured when «Изменить» opened the constructor.
            try:
                eid = int(edit_id or 0)
            except Exception:
                eid = 0
            # remove-old + add-new in ONE atomic write and ONE re-inject; eid=0 → plain add
            res = self._jvoid("replaceGift", ("long", "str"), (eid, json.dumps(entry)))
            if eid > 0:
                self._ctor_edit_id = 0
            # [nosave-fix] honest result: a dropped bridge write must not be announced
            # as «сохранено». Fallback: the same entry through addGifts; only if THAT
            # fails too, report failure.
            ok, text = self._bridge_ok(res)
            if not ok:
                try:
                    res = self._jvoid("addGifts", ("str",), (json.dumps([entry]),))
                except Exception as add_error:
                    res = None
                    text = _cause(add_error)
                if res is None:
                    ok = False
                else:
                    _s = str(res)
                    _low = _s.lower()
                    ok = not any(mk in _low for mk in ("fail", "fatal", "not initialized", "blocked", "exception"))
                    text = _s[:120]
            try: self.log("[edit] save edit_id=%s new_uid=%s -> %s" % (eid, uid, str(res)[:70]))
            except Exception: pass
            if not ok:
                self._toast("не сохранено: " + (text or "ядро не ответило")[:70])
                return False
            self._toast("NFT обновлён ✓" if eid > 0 else "NFT сохранён ✓")
            return True
        except Exception as e:
            self._toast("сборка: " + repr(e)[:140])
            try: self.log("[ctor] build err: " + repr(e))
            except Exception: pass
            return False

    def _build_and_save_batch(self, model_a, pattern_a, backdrop_a, title, num,
                              quantity=1, base_gift_id=0, base_gift=None,
                              value_config=None):
        """Create identical collectibles in one atomic Store update.

        Attribute objects are intentionally reused (they are immutable TL catalog
        values), while every saved gift receives its own id, slug and collectible
        number.  Keeping the whole operation in one addGifts call avoids N profile
        reloads and keeps large batches smooth.
        """
        try:
            quantity = max(1, min(int(quantity or 1), 200))
            issued = int(getattr(self, "_ctor_issued", 0) or 0)
            entries = []
            used_numbers = set()
            import random as _batch_random
            number_cap = max(1, issued if issued > 0 else 999999)
            patterns = list(getattr(self, "_pending_patterns", []) or [])
            for _offset in range(quantity):
                candidate = _batch_random.randint(1, number_cap)
                while candidate in used_numbers and len(used_numbers) < number_cap:
                    candidate = _batch_random.randint(1, number_cap)
                used_numbers.add(candidate)
                random_pattern = _batch_random.choice(patterns) if patterns else pattern_a
                gift, saved, b64, name, slug, uid = self._build_unique_gift(
                    model_a, random_pattern, backdrop_a, title, candidate,
                    base_gift_id, base_gift)
                if not b64:
                    raise RuntimeError("gift serialization failed")
                entry = {
                    "b64": b64, "inject": True, "title": name,
                    "slug": slug, "num": int(candidate), "unique_id": int(uid),
                    "base_gift_id": int(base_gift_id or 0),
                    "gift_kind": "local_upgraded"
                }
                if value_config and str(value_config.get("amount", "") or "").strip():
                    entry["value_config"] = {
                        "amount": str(value_config.get("amount", "")).strip(),
                        "currency": str(value_config.get("currency", "USD") or "USD").upper()
                    }
                entries.append(entry)

            _batch_res = self._jvoid("addGifts", ("str",), (json.dumps(entries),))
            if _batch_res is None or "FAIL" in str(_batch_res) or "not initialized" in str(_batch_res):
                raise RuntimeError("core addGifts: " + str(_batch_res))
            self._toast("Добавлено %d NFT ✓" % len(entries))
            return True
        except Exception as e:
            self._toast("массовое добавление: " + repr(e)[:120])
            try:
                self.log("[ctor] batch save: " + _cause(e))
            except Exception:
                pass
            return False

    def _regular_entry_template(self, gift, title=""):
        """Serialize a base star gift once → a reusable regular-entry template
        (b64 + name + base_gift_id + upgrade info), WITHOUT the per-copy
        unique_id/slug. Returns None on failure."""
        if gift is None or jclass is None:
            return None
        try:
            Saved = jclass("org.telegram.tgnet.tl.TL_stars$TL_savedStarGift")
            saved = Saved()
            saved.gift = gift
            # detect upgradability (base gift has upgrade_stars) — applied to the live
            # wrapper by Java enrich so TG shows the native «Улучшить» button
            try:
                ups = int(getattr(gift, "upgrade_stars", 0) or 0)
            except Exception:
                ups = 0
            SD = jclass("org.telegram.tgnet.SerializedData")
            try:
                size = int(saved.getObjectSize())
            except Exception:
                size = 8192
            sd = SD(max(size, 256))
            saved.serializeToStream(sd)
            data = sd.toByteArray()
            raw = bytes((int(b) & 0xFF) for b in data)
            b64 = base64.b64encode(raw).decode("ascii")
            gid = 0
            try: gid = int(getattr(gift, "id", 0) or 0)
            except Exception: gid = 0
            name = str(title or "").strip() or str(getattr(gift, "title", "") or "").strip() or "Подарок"
            tpl = {"b64": b64, "title": name, "base_gift_id": int(gid), "upgrade_stars": ups}
            return tpl
        except Exception as e:
            try: self.log("[cat] serialize regular: " + _cause(e))
            except Exception: pass
            return None

    def _entry_from_template(self, tpl):
        """Stamp a fresh unique_id/slug onto a template → one persistable entry."""
        import random as _r
        uid = _r.randint(100000000, 999999999)
        name = str(tpl.get("title") or "Подарок")
        entry = {"b64": tpl["b64"], "inject": True, "title": name,
                 "slug": name.replace(" ", "") + "-" + str(uid), "num": 0,
                 "unique_id": int(uid), "base_gift_id": int(tpl.get("base_gift_id") or 0),
                 "gift_kind": "regular"}
        ups = int(tpl.get("upgrade_stars") or 0)
        if ups > 0:
            entry["upgradable"] = True
            entry["upgrade_stars"] = ups
        return entry

    def _add_regular_gifts(self, gift, title="", n=1):
        """Add `n` identical regular gifts in ONE bridge call (single atomic write +
        single reload) — backs the catalog «N×» quantity selector. Returns count added."""
        try:
            try:
                n = int(n or 1)
            except Exception:
                n = 1
            n = max(1, min(n, 99))
            if gift is None or jclass is None:
                self._toast("нет подарка")
                return 0
            tpl = self._regular_entry_template(gift, title)
            if tpl is None:
                self._toast("не удалось сериализовать подарок")
                return 0
            entries = [self._entry_from_template(tpl) for _ in range(n)]
            _reg_res = self._jvoid("addGifts", ("str",), (json.dumps(entries),))
            if _reg_res is None or "FAIL" in str(_reg_res) or "not initialized" in str(_reg_res):
                raise RuntimeError("core addGifts: " + str(_reg_res))
            nm = str(title or "").strip() or str(tpl.get("title") or "подарок")
            if n == 1:
                self._toast("Подарок добавлен ✓")
            else:
                self._toast("Добавлено %d × %s ✓" % (n, nm))
            return n
        except Exception as e:
            self._toast("добавление: " + repr(e)[:140])
            try: self.log("[cat] add regulars: " + _cause(e))
            except Exception: pass
            return 0

    def _add_regular_gift(self, gift, title=""):
        """Add a single plain star gift to the library (thin wrapper over the batch path)."""
        return self._add_regular_gifts(gift, title, 1) > 0

    # How often the loader asks the core whether the answer has landed, and how long it is willing
    # to wait in total. The wait only has to OUTLAST the core's own deadline, so the sheet always
    # ends on the core's honest reason instead of on our impatience.
    _ATTRS_POLL_MS = 300
    _ATTRS_WAIT_MS = 15000
    _ATTRS_PY_WAIT_MS = 12000

    def _fetch_upgrade_attrs(self, gift_id, on_attrs):
        """Fetch the upgrade attributes of `gift_id` → (models, patterns, backdrops, raw),
        delivered on the UI thread EXACTLY ONCE.

        The request runs in the CORE. A Chaquopy dynamic_proxy(RequestDelegate) is the one
        mechanism in this plugin that has repeatedly failed to fire at all on some accounts — no
        response, no error — and that is exactly what «Атрибуты не пришли» was from the device:
        the old code sent the request from Python, waited out its own 10 s deadline and then
        force-resolved with an empty list, which is indistinguishable from a server refusal or
        from a gift that has no attributes. The core's java.lang.Proxy delegates (every gift RPC
        already runs on them) have never needed such a deadline — see PinnedChannel.startPin.

        Two things follow from that: the Python delegate stays only as the fallback for an older
        engine.dex, and every path now records WHY in `_last_attrs_error` so the toast can say it.
        """
        delivered = {"done": False}
        self._last_attrs_error = ""

        def _deliver(models, patterns, backdrops, raw=None, why=""):
            if delivered["done"]:
                return
            delivered["done"] = True
            if raw is None and not (models or patterns or backdrops):
                # Nothing from the network — but the user's own NFTs carry real attribute objects,
                # which is enough for the Python-drawn grid. Never for the native sheet: those are
                # b64-deserialized copies and it crashes on them (see _open_constructor).
                models, patterns, backdrops = self._local_attr_fallback()
                if models or patterns or backdrops:
                    self._toast("Атрибуты не пришли (%s) — беру из своей коллекции"
                                % ((why or "нет ответа")[:60],))
            self._last_attrs_error = str(why or "")
            try:
                on_attrs(models, patterns, backdrops, raw)
            except Exception:
                pass

        if not self._fetch_upgrade_attrs_via_core(gift_id, _deliver):
            self._fetch_upgrade_attrs_in_python(gift_id, _deliver)

    def _fetch_upgrade_attrs_via_core(self, gift_id, deliver):
        """Start the core's fetch and poll it until it answers.

        Returns False when this engine.dex has no such bridge — `_jvoid` answers None both for a
        missing method and for a throwing one, and either way the Python delegate is the only
        remaining option, so the distinction does not matter here."""
        if run_on_ui_thread is None:
            return False
        try:
            gid = int(gift_id or 0)
        except Exception:
            gid = 0
        if gid <= 0:
            return False
        status = self._jvoid("fetchUpgradeAttrs", ("long",), (gid,))
        if status is None:
            return False
        left = {"n": max(1, int(self._ATTRS_WAIT_MS / self._ATTRS_POLL_MS))}

        def _step(text):
            value = str(text or "")
            if value.startswith("ok|"):
                raw = self._jvoid("takeUpgradeAttrs", ("long",), (gid,))
                if raw is None:
                    deliver([], [], [], None, "ядро потеряло атрибуты")
                    return
                models, patterns, backdrops = self._split_attrs(raw)
                deliver(models, patterns, backdrops, raw, "")
                return
            if value.startswith("fail|"):
                deliver([], [], [], None, value[5:])
                return
            left["n"] -= 1
            if left["n"] <= 0:
                deliver([], [], [], None, "ядро не ответило")
                return
            run_on_ui_thread(lambda: _step(self._jvoid("pollUpgradeAttrs", ("long",), (gid,))),
                             self._ATTRS_POLL_MS)

        # Even a cached hit goes through the UI thread: the callback builds a bottom sheet, and
        # nothing guarantees the tap that got here was dispatched on it.
        try:
            run_on_ui_thread(lambda: _step(status))
        except Exception:
            _step(status)
        return True

    def _fetch_upgrade_attrs_in_python(self, gift_id, deliver):
        """Fallback for an engine.dex without `fetchUpgradeAttrs`: send it from here.

        Same shape as the core path — one-shot delivery plus a deadline — because this is the
        delegate that sometimes never fires. The proxy is parked on `self` for the same reason the
        production runtime does it: it has to outlive this frame for Java to call back into it."""
        try:
            if (RequestDelegate is None or get_connections_manager is None
                    or jclass is None or dynamic_proxy is None):
                deliver([], [], [], None, "этот клиент не даёт отправить запрос")
                return
            req = jclass("org.telegram.tgnet.tl.TL_stars$getStarGiftUpgradeAttributes")()
            try:
                req.gift_id = int(gift_id)
            except Exception:
                pass
            plugin = self

            class _D(dynamic_proxy(RequestDelegate)):
                def run(self2, response, error):
                    models, patterns, backdrops = [], [], []
                    raw = None
                    why = ""
                    try:
                        if error is not None:
                            why = str(getattr(error, "text", "") or "") or "Telegram отказал"
                        raw = getattr(response, "attributes", None) if response is not None else None
                        models, patterns, backdrops = plugin._split_attrs(raw)
                        if not why and not (models or patterns or backdrops):
                            why = "у этого подарка нет атрибутов"
                    except Exception as attr_error:
                        why = why or repr(attr_error)[:80]
                    try:
                        run_on_ui_thread(
                            lambda: deliver(models, patterns, backdrops, raw, why))
                    except Exception:
                        deliver(models, patterns, backdrops, raw, why)

            callback = _D()
            self._attrs_callback = callback
            get_connections_manager().sendRequest(req, callback)
            try:
                run_on_ui_thread(lambda: deliver([], [], [], None, "Telegram не ответил"),
                                 self._ATTRS_PY_WAIT_MS)
            except Exception:
                pass
        except Exception as e:
            self.log("[ctor] attrs send: " + _cause(e))
            deliver([], [], [], None, repr(e)[:120])

    def _local_attr_fallback(self):
        """Attribute objects harvested from the user's OWN saved NFTs — the constructor's last
        resort when the server gives nothing, so a failed fetch is a worse constructor rather than
        no constructor at all."""
        try:
            models, patterns, backdrops = self._attr_pools()
            return list(models.values()), list(patterns.values()), list(backdrops.values())
        except Exception as e:
            try:
                self.log("[ctor] local attr pool: " + _cause(e))
            except Exception:
                pass
            return [], [], []

    def _attrs_failed(self, gift_id):
        """One honest message instead of the old catch-all «Атрибуты не пришли».

        That string was shown for a request that timed out, a server refusal and a gift with no
        upgrade attributes alike — which is why the report of it from the device could not be
        acted on at all. `_last_attrs_error` is set by whichever path actually answered."""
        why = str(getattr(self, "_last_attrs_error", "") or "").strip()
        try:
            self.log("[ctor] no attrs for gift_id=%s: %s" % (gift_id, why or "empty response"))
        except Exception:
            pass
        self._toast("Атрибуты не пришли" + ((": " + why[:90]) if why else ""))

    def _jfield(self, obj, name):
        try:
            c = obj.getClass()
            while c is not None:
                try:
                    f = c.getDeclaredField(name)
                    f.setAccessible(True)
                    return f.get(obj)
                except Exception:
                    c = c.getSuperclass()
            return None
        except Exception:
            return None

    def _jset(self, obj, name, val):
        """Reflective field write (walk superclass chain). Returns True on success."""
        if obj is None:
            return False
        try:
            obj.__setattr__(name, val)
            return True
        except Exception:
            pass
        try:
            c = obj.getClass()
            while c is not None:
                try:
                    f = c.getDeclaredField(name)
                    f.setAccessible(True)
                    f.set(obj, val)
                    return True
                except Exception:
                    c = c.getSuperclass()
        except Exception:
            pass
        return False

    def _split_attrs(self, attr_list):
        """Split a raw upgrade-attribute list into (models, patterns, backdrops)."""
        models, patterns, backdrops = [], [], []
        try:
            n = int(attr_list.size()) if attr_list is not None else 0
            for i in range(n):
                a = attr_list.get(i)
                if a is None:
                    continue
                cls = str(a.getClass().getSimpleName()).lower()
                if "model" in cls:
                    models.append(a)
                elif "backdrop" in cls:
                    backdrops.append(a)
                elif "pattern" in cls or "symbol" in cls:
                    patterns.append(a)
        except Exception:
            pass
        return models, patterns, backdrops

    def _saved_attr_objects(self, edit_gift):
        """Extract the (model, pattern, backdrop) attribute objects already stored on a saved gift."""
        model = pattern = backdrop = None
        try:
            gift = self._deserialize_gift(edit_gift.get("b64")) if edit_gift else None
            attrs = getattr(gift, "attributes", None) if gift is not None else None
            n = int(attrs.size()) if attrs is not None else 0
            for i in range(n):
                a = attrs.get(i)
                if a is None:
                    continue
                cls = str(a.getClass().getSimpleName()).lower()
                if "model" in cls and model is None:
                    model = a
                elif "backdrop" in cls and backdrop is None:
                    backdrop = a
                elif ("pattern" in cls or "symbol" in cls) and pattern is None:
                    pattern = a
        except Exception:
            pass
        return model, pattern, backdrop

    def _find_base_gift(self, gid):
        """Locate the base catalog TL_starGift by its id (for availability/name/document)."""
        try:
            gid = int(gid or 0)
            if gid <= 0:
                return None
            for g in self._catalog_list():
                try:
                    if int(getattr(g, "id", 0) or 0) == gid:
                        return g
                except Exception:
                    continue
        except Exception:
            pass
        return None

    def _copy_availability(self, gift, base_gift, num):
        """Fill availability_total / availability_issued so the «Количество» row isn't 0/0."""
        def _rdi(obj, names):
            for nm in names:
                try:
                    v = int(getattr(obj, nm, 0) or 0)
                    if v > 0:
                        return v
                except Exception:
                    pass
            return 0
        total = issued = 0
        if base_gift is not None:
            total = _rdi(base_gift, ["availability_total", "total", "limited_count"])
            issued = _rdi(base_gift, ["availability_issued", "issued"])
        if total <= 0:
            total = 10000  # sane non-zero so the ribbon/row renders
        if issued <= 0:
            issued = min(int(num or 1), int(total))
        for nm in ("availability_total", "total"):
            if self._jset(gift, nm, int(total)):
                break
        for nm in ("availability_issued", "issued"):
            if self._jset(gift, nm, int(issued)):
                break
        self._jset(gift, "availability_remains", max(int(total) - int(issued), 0))
        self._jset(gift, "limited", True)

    def _seed_sheet(self, sheet, seed):
        """Pre-select (model, pattern, backdrop) on the native sheet so it shows the
        saved/base combo instead of a random one — and drops the «Случайные» subtitle."""
        if sheet is None:
            return
        model, pattern, backdrop = seed if seed else (None, None, None)
        if model is None and pattern is None and backdrop is None:
            return
        try:
            PreviewAttrs = jclass("org.telegram.ui.Stars.StarGiftPreviewSheet$Attributes")
            attrs_obj = PreviewAttrs(backdrop, pattern, model)
        except Exception as e:
            self.log("[ctor] seed attrs cls: " + _cause(e))
            return
        self._jset(sheet, "selectedAttributes", attrs_obj)
        try:
            tv = self._jfield(sheet, "topView")
            if tv is not None:
                try: tv.setPreviewAttributes(attrs_obj)
                except Exception: pass
                try:
                    AL = jclass("java.util.ArrayList")
                    lst = AL()
                    for o in (model, pattern, backdrop):
                        if o is not None:
                            lst.add(o)
                    tv.setPreviewingAttributes(lst)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            ModeCls = jclass("org.telegram.ui.Stars.StarGiftPreviewSheet$Mode")
            mode = None
            try:
                mode = getattr(ModeCls, "SELECTED")
            except Exception:
                try: mode = ModeCls.valueOf("SELECTED")
                except Exception: mode = None
            if mode is not None:
                sheet.setMode(mode)
        except Exception:
            pass
        try:
            sheet.updateHeaderAttributes(False)
        except Exception:
            pass

    def _open_constructor(self, edit_gift):
        if BottomSheet is None or jclass is None:
            self._toast("UI недоступен")
            return
        # remember which saved gift we're EDITING so the save REPLACES it (not duplicate)
        try:
            self._ctor_edit_id = int((edit_gift or {}).get("unique_id") or (edit_gift or {}).get("saved_id") or 0)
        except Exception:
            self._ctor_edit_id = 0
        try:
            self.log("[edit] open edit_id=%s (uid=%s saved=%s kind=%s)" % (
                self._ctor_edit_id, (edit_gift or {}).get("unique_id"),
                (edit_gift or {}).get("saved_id"), (edit_gift or {}).get("kind")))
        except Exception:
            pass
        gid = 0
        if edit_gift:
            try:
                gid = int(edit_gift.get("base_gift_id") or 0) or int(edit_gift.get("unique_id") or 0)
            except Exception:
                gid = 0
        if gid <= 0:
            # new gift with no base id → derive a base from the first library gift
            for g in self._gifts():
                gid = int(g.get("base_gift_id") or 0) or int(g.get("unique_id") or 0)
                if gid > 0:
                    break
        if gid <= 0:
            self._toast("Нет base_gift_id — добавь NFT из каталога")
            return
        title = (edit_gift.get("title") if edit_gift else "NFT") or "NFT"
        num = (edit_gift.get("num") if edit_gift else 1) or 1
        # issued/total cap for the «random collectible number» button (≤ выпущено).
        # Prefer the saved avail_*; base_gift refines it later in _show_native_constructor.
        self._ctor_issued = 0
        try:
            for k in ("avail_issued", "availability_issued", "avail_total", "availability_total", "limit_total"):
                v = int((edit_gift or {}).get(k) or 0)
                if v > 0:
                    self._ctor_issued = v; break
        except Exception:
            self._ctor_issued = 0
        # pre-select the attributes already saved on this gift (so edit ≠ random)
        seed = self._saved_attr_objects(edit_gift) if edit_gift else None
        self._toast("загружаю атрибуты…")

        def _on(models, patterns, backdrops, raw):
            # NEVER let this async UI-thread callback raise — an escaped exception here
            # force-closes Telegram («вылетает»).
            try:
                if raw is None or int(getattr(raw, "size", lambda: 0)()) <= 0:
                    if not (models or patterns or backdrops):
                        self._attrs_failed(gid)
                        return
                    self._show_constructor_grid(edit_gift, models, patterns, backdrops, base_gift_id=gid)
                    return
                # EDIT: map the saved gift's attrs to the LIVE objects (the ones in `raw`).
                # Passing the b64-deserialized objects to the native sheet crashes it.
                live_seed = self._match_seed_to_live(seed, models, patterns, backdrops) if seed else None
                vcfg = edit_gift.get("value_config") if edit_gift else None
                self._show_native_constructor(gid, title, num, raw, seed=live_seed,
                                              base_gift=self._find_base_gift(gid), value_cfg=vcfg)
            except Exception as e:
                self._toast("конструктор: " + repr(e)[:120])
                try: self.log("[ctor] _on: " + _cause(e))
                except Exception: pass
        self._fetch_upgrade_attrs(gid, _on)

    def _attr_id(self, a):
        for nm in ("document_id", "documentId", "backdrop_id", "backdropId", "id"):
            try:
                v = int(getattr(a, nm, 0) or 0)
                if v:
                    return v
            except Exception:
                pass
        # backdrops have no doc id → fall back to the name
        try:
            return ("n:" + str(getattr(a, "name", "") or "")).strip()
        except Exception:
            return 0

    def _match_seed_to_live(self, seed, models, patterns, backdrops):
        """Return (model,pattern,backdrop) using the LIVE attr instances (from the fetched
        list) that match the saved gift's attrs by id — so the native sheet never sees a
        foreign object. Falls back to None per-slot (no seed) rather than a wrong object."""
        try:
            sm, sp, sb = seed
        except Exception:
            return None

        def _pick(saved, live_list):
            try:
                if saved is None or not live_list:
                    return None
                sid = self._attr_id(saved)
                if sid:
                    for a in live_list:
                        try:
                            if self._attr_id(a) == sid:
                                return a
                        except Exception:
                            continue
            except Exception:
                pass
            return None
        return (_pick(sm, models), _pick(sp, patterns), _pick(sb, backdrops))

    def _install_ctor_hooks(self):
        """Lazily disable the attribute-cell selection-ring animation (cold path: the
        cell only exists while the constructor sheet is open). The previous model's
        ring used to fade out with an overshoot («появляется 2 раза») — forcing the
        `animated` arg of GiftAttributeCell.setSelected(boolean[,boolean]) to false
        makes the ring snap instantly. Robust: tries several class names + signatures
        and logs exactly what it found so we can diagnose a miss."""
        if getattr(self, "_ctor_hooks_done", False):
            return
        if MethodHook is None or getattr(self, "hook_method", None) is None or _NoAnimSelectHook is None:
            return
        self._ctor_hooks_done = True  # one-shot; don't retry on every open
        Cell = None
        for cn in ("org.telegram.ui.Stars.GiftAttributeCell",
                   "org.telegram.ui.Gifts.GiftAttributeCell",
                   "org.telegram.ui.Stars.StarGiftSheet$GiftAttributeCell"):
            try:
                Cell = JavaClass.forName(cn)
                self.log("[ctor] GiftAttributeCell = " + cn)
                break
            except Exception:
                continue
        if Cell is None:
            self.log("[ctor] GiftAttributeCell NOT FOUND (tried Stars/Gifts/nested)")
            return
        refs = []
        seen = []
        try:
            for m in Cell.getDeclaredMethods():
                try:
                    if m.getName() != "setSelected":
                        continue
                    pts = m.getParameterTypes()
                    sig = ",".join(p.getName() for p in pts)
                    seen.append(sig or "(void)")
                    # the 2-arg setSelected(selected, animated) — force animated=false
                    if len(pts) == 2 and pts[0].getName() == "boolean" and pts[1].getName() == "boolean":
                        m.setAccessible(True)
                        refs.append(self.hook_method(m, _NoAnimSelectHook()))
                except Exception:
                    continue
        except Exception as e:
            self.log("[ctor] setSelected hook err: " + _cause(e))
        try:
            SheetCls = JavaClass.forName("org.telegram.ui.Stars.StarGiftPreviewSheet")
            for method in SheetCls.getDeclaredMethods():
                if method.getName() == "newSelectedWithCurrentTab" and method.getParameterCount() == 1:
                    method.setAccessible(True)
                    refs.append(self.hook_method(method, _CtorManualHook(self)))
                    break
        except Exception as e:
            self.log("[ctor] manual selection hook: " + _cause(e))
        self._ctor_hook_refs = refs
        self.log("[ctor] setSelected sigs=%s hooked=%d" % (seen, len(refs)))

    def _kill_sheet_anim(self, sheet):
        """Null out the RecyclerView item-animator (and zero its durations as a
        fallback) on the constructor sheet. When you switch a model the native
        DefaultItemAnimator cross-fades the rebound cells → the previously-selected
        outline blinks with a delay. With no animator the selection ring snaps."""
        try:
            rv = self._jfield(sheet, "recyclerListView")
            if rv is None:
                self.log("[ctor] no recyclerListView for anim-kill")
                return
            anim = None
            try:
                anim = rv.getItemAnimator()
            except Exception:
                anim = None
            # zero the durations first (covers code paths that re-set the animator)
            if anim is not None:
                for setter, val in (("setAddDuration", 0), ("setRemoveDuration", 0),
                                    ("setMoveDuration", 0), ("setChangeDuration", 0)):
                    try:
                        getattr(anim, setter)(val)
                    except Exception:
                        pass
                try:
                    anim.setSupportsChangeAnimations(False)
                except Exception:
                    pass
            try:
                rv.setItemAnimator(None)
                self.log("[ctor] itemAnimator killed (had=%s)" % (anim is not None))
            except Exception as e:
                self.log("[ctor] setItemAnimator(None): " + _cause(e))
        except Exception as e:
            self.log("[ctor] anim-kill: " + _cause(e))

    # ---- constructor header pills: «#номер» (collectible num) + «$ценность» (value+currency) ----
    def _col(self, argb):
        """Coerce an 0xAARRGGBB literal into a signed 32-bit Java int (Chaquopy-safe)."""
        argb &= 0xFFFFFFFF
        return argb - 0x100000000 if argb >= 0x80000000 else argb

    def _curr_symbol(self, c):
        return {"USD": "$", "EUR": "€", "RUB": "₽"}.get(str(c or "USD").upper(), "$")

    #: Above this perceived brightness a fill counts as light and takes dark text. The client
    #: uses 0.721 for the same decision, but that is for its bold badge glyph; our chips are
    #: 13sp text, and the lavender accent this theme uses sits at ~0.70 — just under the
    #: client's line, which is exactly the white-on-lavender the owner could not read. A
    #: saturated blue accent (#3390EC ≈ 0.51) is still comfortably below and keeps white.
    _LIGHT_FILL_BRIGHTNESS = 0.6

    def _ink_on(self, fill):
        """Readable text colour for something drawn ON `fill`.

        Hardcoding white was wrong: `key_featuredStickers_addButton` is a light lavender in
        several themes, and white-on-lavender is barely legible. The brightness test itself
        is the one the client applies when it has to put text on an arbitrary colour — see
        `StarRatingView.Colors.update`.
        """
        try:
            bright = float(AndroidUtilities.computePerceivedBrightness(int(fill)))
        except Exception:
            try:
                value = int(fill) & 0xFFFFFF
                bright = (((value >> 16) & 0xFF) * 0.2126 + ((value >> 8) & 0xFF) * 0.7152
                          + (value & 0xFF) * 0.0722) / 255.0
            except Exception:
                bright = 0.0
        return self._col(0xFF000000 if bright > self._LIGHT_FILL_BRIGHTNESS else 0xFFFFFFFF)

    def _ctor_num_label(self):
        try:
            return "#" + str(int(getattr(self, "_ctor_num", 1) or 1))
        except Exception:
            return "#1"

    def _ctor_value_label(self):
        v = str(getattr(self, "_ctor_value", "") or "").strip()
        sym = self._curr_symbol(getattr(self, "_ctor_currency", "USD"))
        if not v:
            return sym
        # «≈» prefix while the price is auto-derived from attributes (an estimate the
        # owner can still override); plain symbol once they type their own value
        auto = getattr(self, "_ctor_value_auto", False)
        return (("≈ " if auto else "") + sym + " " + v)

    def _ctor_pill(self, ctx, text):
        tv = TextView(ctx)
        tv.setText(text)
        tv.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 13)
        tv.setTextColor(self._col(0xFFFFFFFF))
        tv.setGravity(Gravity.CENTER)
        tv.setPadding(AndroidUtilities.dp(11), AndroidUtilities.dp(5),
                      AndroidUtilities.dp(11), AndroidUtilities.dp(5))
        bg = GradientDrawable()
        bg.setCornerRadius(AndroidUtilities.dp(13))
        bg.setColor(self._col(0x55000000))
        tv.setBackground(bg)
        return tv

    def _qty_pill_view(self, ctx, text):
        """Accent FAB-style pill for the catalog quantity selector («N×»)."""
        tv = TextView(ctx)
        tv.setText(text)
        tv.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 16)
        tv.setTextColor(self._col(0xFFFFFFFF))
        tv.setGravity(Gravity.CENTER)
        tv.setPadding(AndroidUtilities.dp(22), AndroidUtilities.dp(12),
                      AndroidUtilities.dp(22), AndroidUtilities.dp(12))
        bg = GradientDrawable()
        bg.setCornerRadius(AndroidUtilities.dp(26))
        try:
            bg.setColor(Theme.getColor(Theme.key_featuredStickers_addButton))
        except Exception:
            bg.setColor(self._col(0xFF3390EC))
        tv.setBackground(bg)
        try:
            tv.setElevation(float(AndroidUtilities.dp(4)))
        except Exception:
            pass
        return tv

    def _inject_ctor_pills(self, sheet):
        """Add the «#num» (left) and «$value» (right) pills into the native sheet
        header, next to the back / play buttons (matches the production look)."""
        if PopupWindow is None:
            return
        try:
            header = self._jfield(sheet, "headerView")
            if header is None:
                self.log("[ctor] no headerView for pills")
                return
            ctx = header.getContext()
            # left: collectible number
            np = self._ctor_pill(ctx, self._ctor_num_label())
            self._ctor_num_pill = np
            lp1 = FrameLayout.LayoutParams(-2, -2, Gravity.TOP | Gravity.LEFT)
            lp1.leftMargin = AndroidUtilities.dp(52)
            lp1.topMargin = AndroidUtilities.dp(15)
            np.setOnClickListener(self._click(lambda v: self._open_num_pad(np)))
            header.addView(np, lp1)
            # right: value + currency
            vp = self._ctor_pill(ctx, self._ctor_value_label())
            self._ctor_value_pill = vp
            lp2 = FrameLayout.LayoutParams(-2, -2, Gravity.TOP | Gravity.RIGHT)
            lp2.rightMargin = AndroidUtilities.dp(52)
            lp2.topMargin = AndroidUtilities.dp(15)
            vp.setOnClickListener(self._click(lambda v: self._open_value_pad(vp)))
            header.addView(vp, lp2)
            self.log("[ctor] pills injected")
        except Exception as e:
            self.log("[ctor] pills: " + _cause(e))

    # A keypad where every key feels identical is the giveaway that it is drawn, not native:
    # a digit, a backspace and the commit key are three different actions.
    _NUMPAD_HAPTICS = {"OK": "impact", "Del": "tick", "Clr": "crunch",
                       "USD": "coin", "EUR": "coin", "RUB": "coin"}

    def _np_btn(self, ctx, label, on_tap):
        b = TextView(ctx)
        b.setText(label)
        b.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 15)
        b.setTextColor(self._col(0xFFFFFFFF))
        b.setGravity(Gravity.CENTER)
        bg = GradientDrawable()
        bg.setCornerRadius(AndroidUtilities.dp(10))
        bg.setColor(self._col(0x18FFFFFF))
        b.setBackground(bg)
        text = str(label)
        hap = self._NUMPAD_HAPTICS.get(text, "spin" if text.startswith("🎲") else "press")
        b.setOnClickListener(self._click(lambda v: on_tap(), hap=hap))
        return b

    def _show_numpad(self, anchor, kind, on_done):
        """Generic keypad popup anchored to a pill. kind = 'num' | 'value'.
        on_done(text, currency) is called on OK."""
        try:
            ctx = anchor.getContext()
        except Exception:
            return
        is_val = (kind == "value")
        if is_val:
            buf = {"s": str(getattr(self, "_ctor_value", "") or "").strip()}
            cur = {"c": str(getattr(self, "_ctor_currency", "USD") or "USD").upper()}
        else:
            buf = {"s": str(int(getattr(self, "_ctor_num", 1) or 1))}
            cur = {"c": "USD"}

        root = LinearLayout(ctx)
        root.setOrientation(LinearLayout.VERTICAL)
        rbg = GradientDrawable()
        rbg.setCornerRadius(AndroidUtilities.dp(16))
        rbg.setColor(self._col(0xF21D1D27))
        root.setBackground(rbg)
        pad = AndroidUtilities.dp(6)
        root.setPadding(pad, pad, pad, pad)

        title = TextView(ctx)
        title.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 14)
        title.setTextColor(self._col(0xFFFFFFFF))
        title.setGravity(Gravity.CENTER)
        title.setPadding(0, AndroidUtilities.dp(2), 0, AndroidUtilities.dp(6))

        def _title_text():
            if is_val:
                s = buf["s"]
                return (self._curr_symbol(cur["c"]) + " " + s) if s else self._curr_symbol(cur["c"])
            return "#" + buf["s"]

        def _refresh():
            try:
                title.setText(_title_text())
            except Exception:
                pass
        _refresh()
        root.addView(title, LinearLayout.LayoutParams(-1, -2))

        pop = {"w": None}
        fresh = {"v": True}   # first keypress replaces the prefilled value

        def _digit(d):
            if fresh["v"]:
                fresh["v"] = False
                buf["s"] = "" if d != "." else "0"
            s = buf["s"]
            if d == "." :
                if "." in s or not is_val:
                    return
                if not s:
                    s = "0"
                buf["s"] = s + "."
            else:
                # cap length (num: 6 digits; value: 9 chars)
                limit = 9 if is_val else 6
                if len(s) >= limit:
                    return
                if s == "0" and d != ".":
                    s = ""
                buf["s"] = s + d
            _refresh()

        def _del():
            fresh["v"] = False
            buf["s"] = buf["s"][:-1]
            _refresh()

        def _clr():
            fresh["v"] = False
            buf["s"] = ""
            _refresh()

        def _rand():
            # random collectible number that doesn't exceed the issued/total supply
            import random as _r
            fresh["v"] = False
            cap = int(getattr(self, "_ctor_issued", 0) or 0)
            if cap <= 0:
                cap = 99999
            cap = min(cap, 999999)            # the «#num» field caps at 6 digits
            buf["s"] = str(_r.randint(1, max(1, cap)))
            _refresh()

        def _cycle():
            order = ["USD", "EUR", "RUB"]
            try:
                i = order.index(cur["c"])
            except Exception:
                i = 0
            cur["c"] = order[(i + 1) % 3]
            _refresh()

        def _ok():
            try:
                if pop["w"] is not None:
                    pop["w"].dismiss()
            except Exception:
                pass
            try:
                on_done(buf["s"], cur["c"])
            except Exception as e:
                self.log("[ctor] numpad ok: " + _cause(e))

        def _row(cells):
            row = LinearLayout(ctx)
            row.setOrientation(LinearLayout.HORIZONTAL)
            for label, fn in cells:
                lp = LinearLayout.LayoutParams(0, AndroidUtilities.dp(38), 1.0)
                m = AndroidUtilities.dp(2)
                lp.setMargins(m, m, m, m)
                row.addView(self._np_btn(ctx, label, fn), lp)
            root.addView(row, LinearLayout.LayoutParams(-1, -2))

        for a, b, c in (("1", "2", "3"), ("4", "5", "6"), ("7", "8", "9")):
            _row([(a, lambda d=a: _digit(d)), (b, lambda d=b: _digit(d)), (c, lambda d=c: _digit(d))])
        if is_val:
            _row([(".", lambda: _digit(".")), ("0", lambda: _digit("0")), ("Del", _del)])
            _row([(cur["c"], _cycle), ("Clr", _clr), ("OK", _ok)])
        else:
            _row([("Del", _del), ("0", lambda: _digit("0")), ("OK", _ok)])
            _row([("🎲 Случайный №", _rand)])   # random # ≤ выпущено

        w = PopupWindow(root, AndroidUtilities.dp(188), -2, True)
        pop["w"] = w
        try:
            w.setOutsideTouchable(True)
            w.setBackgroundDrawable(GradientDrawable())
        except Exception:
            pass
        try:
            w.showAsDropDown(anchor, 0, AndroidUtilities.dp(4))
            root.setAlpha(0.0); root.setScaleX(0.90); root.setScaleY(0.90)
            root.setTranslationY(float(-AndroidUtilities.dp(8)))
            na = root.animate().alpha(1.0).scaleX(1.0).scaleY(1.0).translationY(0.0).setDuration(210)
            it = self._smooth_interp()
            if it is not None: na.setInterpolator(it)
            na.start()
            self._stagger_children(root, 15, 24, 4)
        except Exception as e:
            self.log("[ctor] numpad show: " + _cause(e))

    def _open_num_pad(self, pill):
        def _done(text, _cur):
            try:
                n = int(text or "1")
            except Exception:
                n = 1
            self._ctor_num = max(n, 1)
            try:
                pill.setText(self._ctor_num_label())
            except Exception:
                pass
            # collectible number affects the auto price (low # = pricier) → re-fill now
            self._refresh_auto_value()
        self._show_numpad(pill, "num", _done)

    def _open_ctor_qty_pad(self, pill):
        def _done(text, _cur):
            try:
                qty = int(text or "1")
            except Exception:
                qty = 1
            self._ctor_qty = max(1, min(qty, 99))
            try:
                pill.setText(str(self._ctor_qty) + "×")
            except Exception:
                pass
        self._show_numpad(pill, "num", _done)

    def _inject_ctor_batch_button(self, sheet, gid, title, num):
        """Native floating multi-create action, aligned with Telegram's preview controls."""
        try:
            header = self._jfield(sheet, "headerView")
            send_button = self._jfield(sheet, "headerPlay")
            if header is None:
                return
            ctx = header.getContext()
            button = self._tg_icon_button(
                ctx, ("menu_premium_effects", "settings_stars", "filled_giveaway_stars"),
                self._col(0xFFFFFFFF), "Создать несколько NFT",
                lambda v: self._open_batch_quantity(sheet, gid, title, num))
            self._ctor_batch_button = button
            button.setEnabled(False)
            button.setAlpha(0.34)
            try:
                bg = GradientDrawable()
                bg.setShape(GradientDrawable.OVAL)
                bg.setColor(self._col(0x7A000000))
                button.setBackground(self._ripple_bg(
                    bg, Theme.getColor(Theme.key_featuredStickers_addButton)))
                button.setPadding(AndroidUtilities.dp(9), AndroidUtilities.dp(9),
                                  AndroidUtilities.dp(9), AndroidUtilities.dp(9))
            except Exception:
                pass
            size = AndroidUtilities.dp(42)
            lp = FrameLayout.LayoutParams(size, size, Gravity.RIGHT | Gravity.TOP)
            lp.rightMargin = AndroidUtilities.dp(13)
            lp.topMargin = AndroidUtilities.dp(69)
            # Anchor to the same header container as Telegram's send action.
            # This keeps the vertical offset stable across screen sizes.
            header.addView(button, lp)
            self._ctor_batch_poll_gen = int(getattr(self, "_ctor_batch_poll_gen", 0) or 0) + 1
            generation = self._ctor_batch_poll_gen

            # `_nat_sheet` is only cleared on the save and open-catalog paths — nothing clears it
            # when the user simply swipes the constructor away or presses back. Without the
            # attachment backstop below, that leaves this 180 ms reflective tick running for the
            # rest of the process, holding the sheet, its header and the Activity behind them.
            # Detachment is only trusted AFTER the button has been seen on screen once: the poll is
            # armed 450 ms in and must not mistake "not laid out yet" for "dismissed".
            seen_attached = [False]

            def _poll():
                if generation != getattr(self, "_ctor_batch_poll_gen", 0):
                    return
                if getattr(self, "_nat_sheet", None) is not sheet:
                    return
                try:
                    attached = bool(button.isAttachedToWindow())
                except Exception:
                    attached = True          # host without the API → keep the previous behaviour
                if attached:
                    seen_attached[0] = True
                elif seen_attached[0]:
                    self._nat_sheet = None   # it was on screen and no longer is → dismissed
                    return
                model, _pattern, backdrop = self._read_sheet_attrs(sheet)
                ready = model is not None and backdrop is not None
                try:
                    was = bool(button.isEnabled())
                    button.setEnabled(ready)
                    if ready != was:
                        button.animate().alpha(1.0 if ready else 0.34).scaleX(
                            1.0 if ready else 0.92).scaleY(
                            1.0 if ready else 0.92).setDuration(180).start()
                except Exception:
                    pass
                run_on_ui_thread(_poll, 180)
            run_on_ui_thread(_poll, 450)
        except Exception as e:
            self.log("[ctor] batch button: " + _cause(e))

    def _open_batch_quantity(self, sheet, gid, title, num):
        model, _pattern, backdrop = self._read_sheet_attrs(sheet)
        if model is None or backdrop is None:
            self._toast("Сначала выбери модель и фон")
            return
        try:
            frag = get_last_fragment()
            ctx = frag.getParentActivity() if frag else None
            if ctx is None or AlertDialogBuilder is None:
                return
            values = (1, 5, 10, 25, 50, 100, 150, 200)
            labels = [str(v) + " подарков" for v in values] + ["Своё количество…"]

            def _start(quantity):
                self._ctor_qty = max(1, min(int(quantity), 200))
                run_on_ui_thread(lambda: self._save_from_native(sheet, gid, title, num), 120)

            def _custom():
                def _submit(text):
                    try:
                        quantity = int(str(text or "").strip())
                    except Exception:
                        self._toast("Введи число от 1 до 200")
                        return
                    if quantity < 1 or quantity > 200:
                        self._toast("Можно создать от 1 до 200 подарков")
                        return
                    _start(quantity)
                self._input("Количество подарков (1–200)", "", _submit, numeric=True)

            def _choose(dialog, index):
                try: dialog.dismiss()
                except Exception: pass
                if index < 0:
                    return
                if index < len(values):
                    _start(values[index])
                elif index == len(values):
                    run_on_ui_thread(_custom, 100)

            builder = AlertDialogBuilder(ctx)
            builder.set_title("Создать несколько NFT")
            builder.set_items(labels, _choose)
            builder.set_negative_button("Отмена", None)
            run_on_ui_thread(builder.show)
        except Exception as e:
            self.log("[ctor] batch quantity: " + _cause(e))
            self._toast("Не удалось открыть выбор количества")

    def _open_value_pad(self, pill):
        def _done(text, curncy):
            t = str(text or "").strip()
            self._ctor_value = t
            self._ctor_currency = str(curncy or "USD").upper()
            if t:
                # owner typed a price → manual override, stop auto-deriving
                self._ctor_value_auto = False
            else:
                # cleared the field → re-enable auto and re-fill from current attributes
                self._ctor_value_auto = True
                self._refresh_auto_value()
                self._start_autovalue_loop()
            try:
                pill.setText(self._ctor_value_label())
            except Exception:
                pass
        self._show_numpad(pill, "value", _done)

    def _show_native_constructor(self, gid, title, num, attr_list, seed=None, base_gift=None, value_cfg=None):
        try:
            self._install_ctor_hooks()
            self._ctor_qty = 1
            self._ctor_manual_model = False
            self._ctor_manual_backdrop = False
            # constructor pill state (collectible number + value/currency)
            try:
                self._ctor_num = int(num or 1) or 1
            except Exception:
                self._ctor_num = 1
            # refine the «random number» cap from the base catalog gift (issued/total supply)
            try:
                if base_gift is not None:
                    c = int(getattr(base_gift, "availability_issued", 0) or 0) or \
                        int(getattr(base_gift, "availability_total", 0) or 0)
                    if c > 0:
                        self._ctor_issued = c
            except Exception:
                pass
            self._ctor_value = ""
            self._ctor_currency = "USD"
            if value_cfg:
                try:
                    self._ctor_value = str(value_cfg.get("amount", "") or "").strip()
                    self._ctor_currency = str(value_cfg.get("currency", "USD") or "USD").upper()
                except Exception:
                    pass
            # AUTO price unless the gift already has a saved (manual) value — then respect it.
            # In auto mode the value is derived live from the selected attributes' rarity.
            self._ctor_value_auto = not bool(str(self._ctor_value).strip())
            # match the owner's TG locale: default the currency to the gift's own
            # value_currency (so the estimate reads «≈ €8 116» like the native sheet)
            if self._ctor_value_auto and base_gift is not None:
                try:
                    gc = str(getattr(base_gift, "value_currency", "") or "").upper()
                    if gc in ("USD", "EUR", "RUB"):
                        self._ctor_currency = gc
                except Exception:
                    pass
            frag = get_last_fragment()
            act = frag.getParentActivity() if frag else None
            if act is None:
                self._toast("нет контекста")
                return
            # remember the base gift so the save step can copy name / availability / document
            self._pending_base_gift = base_gift
            _ms, _ps, _bs = self._split_attrs(attr_list)
            self._pending_patterns = list(_ps or [])
            self._ctor_anchor_usd = None                 # force re-resolve the value anchor
            # if no explicit seed, default to the FIRST option of each kind (stable, never random)
            if seed is None:
                ms, ps, bs = self._split_attrs(attr_list)
                seed = (ms[0] if ms else None, ps[0] if ps else None, bs[0] if bs else None)
            Sheet = jclass("org.telegram.ui.Stars.StarGiftPreviewSheet")
            rp = None
            try:
                rp = frag.getResourceProvider()
            except Exception:
                rp = None
            sheet = Sheet(act, rp, _selected_account(), str(title), attr_list, False)
            self._nat_sheet = sheet
            sheet.show()
            # kill the list item-animator so switching a model doesn't fade the
            # previously-selected cell's outline («обводка мерцает на прошлых моделях»)
            self._kill_sheet_anim(sheet)
            # repurpose the native headerPlay button as «save NFT to library»
            try:
                btn = self._jfield(sheet, "headerPlay")
                if btn is not None:
                    try:
                        from org.telegram.messenger import R as _R
                        ic = int(getattr(_R.drawable, "msg_send", 0) or 0) or int(getattr(_R.drawable, "ic_ab_done", 0) or 0)
                        if ic:
                            btn.setImageResource(ic)
                    except Exception:
                        pass
                    btn.setOnClickListener(self._click(lambda v: self._save_from_native(sheet, gid, title, num), hap="impact"))
            except Exception as e:
                self.log("[ctor] hook btn: " + repr(e))
            # seed the selected combo AFTER the sheet built its views (slight delay)
            run_on_ui_thread(lambda: self._seed_sheet(sheet, seed), 60)
            # inject the «#num» / «$value» pills into the header
            run_on_ui_thread(lambda: self._inject_ctor_pills(sheet), 80)
            run_on_ui_thread(lambda: self._inject_ctor_batch_button(sheet, gid, title, num), 110)
            # start the live auto-price loop (fills «$value» from the selected attributes,
            # refreshing as the owner switches model / backdrop / symbol)
            self._start_autovalue_loop()
        except Exception as e:
            self._toast("конструктор: " + repr(e)[:140])
            self.log("[ctor] native: " + _cause(e))

    def _read_sheet_attrs(self, sheet):
        """Current model / pattern / backdrop selected in the native StarGiftPreviewSheet —
        from `selectedAttributes`, falling back to the topView getters."""
        model = pattern = backdrop = None
        try:
            attrs = self._jfield(sheet, "selectedAttributes")
            if attrs is not None:
                model = getattr(attrs, "model", None)
                pattern = getattr(attrs, "pattern", None)
                backdrop = getattr(attrs, "backdrop", None)
        except Exception:
            pass
        if model is None and pattern is None and backdrop is None:
            try:
                tv = self._jfield(sheet, "topView")
                if tv is not None:
                    try: model = tv.getUpgradeImageViewAttribute()
                    except Exception: pass
                    try: pattern = tv.getUpgradePatternAttribute()
                    except Exception: pass
                    try: backdrop = tv.getUpgradeBackdropAttribute()
                    except Exception: pass
            except Exception:
                pass
        return model, pattern, backdrop

    def _save_from_native(self, sheet, gid, title, num):
        try:
            model, pattern, backdrop = self._read_sheet_attrs(sheet)
            base_gift = getattr(self, "_pending_base_gift", None)
            edit_id = int(getattr(self, "_ctor_edit_id", 0) or 0)
            # num + value/currency come from the header pills
            try:
                num = int(getattr(self, "_ctor_num", num) or num or 1)
            except Exception:
                num = num or 1
            value_cfg = None
            val = str(getattr(self, "_ctor_value", "") or "").strip()
            if val:
                value_cfg = {"amount": val,
                             "currency": str(getattr(self, "_ctor_currency", "USD") or "USD").upper()}
            quantity = max(1, min(int(getattr(self, "_ctor_qty", 1) or 1), 200))
            if edit_id > 0 or quantity == 1:
                ok = self._build_and_save(model, pattern, backdrop, title, num,
                                          base_gift_id=gid, base_gift=base_gift,
                                          value_config=value_cfg, edit_id=edit_id)
            else:
                ok = self._build_and_save_batch(
                    model, pattern, backdrop, title, num, quantity,
                    base_gift_id=gid, base_gift=base_gift, value_config=value_cfg)
            if ok:
                self._nat_sheet = None          # stop the live auto-price loop
                try: sheet.dismiss()
                except Exception: pass
                try:
                    if getattr(self, "_catalog_sheet", None) is not None:
                        self._catalog_sheet.dismiss()
                    if getattr(self, "_gifts_sheet", None) is not None:
                        self._gifts_sheet.dismiss()
                except Exception:
                    pass
        except Exception as e:
            self._toast("сохранение: " + repr(e)[:140])

    def _attr_name(self, a):
        try:
            return str(getattr(a, "name", "") or "")
        except Exception:
            return ""

    def _attr_rarity(self, a):
        try:
            v = int(getattr(a, "rarity_permille", 0) or 0)
            return (v / 10.0)
        except Exception:
            return 0.0

    # ---- automatic collectible value (anchored on the gift's REAL market price, like TG) ----
    # Telegram fills «Ценность» from the gift's own value_amount/value_currency (and the
    # resale floor resell_min_stars). A Plush Pepe is worth thousands NOT because of a
    # formula but because that's its market floor — so we ANCHOR on that real number and let
    # rarity / collectible-number only nudge it, instead of inventing a price from scratch.
    _STAR_USD = 0.013                                    # ≈ USD per Telegram Star (floor→USD)
    _FX = _USD_PER_UNIT                                  # → USD per 1 unit (see _fiat_for_ton)

    def _to_usd(self, amount, currency):
        return float(amount) * self._FX.get(str(currency or "USD").upper(), 1.0)

    def _from_usd(self, usd, currency):
        r = self._FX.get(str(currency or "USD").upper(), 1.0)
        return (float(usd) / r) if r else float(usd)

    def _gift_value_anchor_usd(self, bg):
        """The gift's REAL value in USD, taken from its own economics (the same data TG uses
        for «Ценность»). Priority: shown value → resale floor → controller floor → mint price.
        Returns (usd, source-tag); (0.0, '') when nothing is known."""
        if bg is None:
            return 0.0, ""
        # 1) the displayed value: value_amount (minor units, exp=2 for USD/EUR/RUB) + value_currency
        try:
            va = int(getattr(bg, "value_amount", 0) or 0)
            if va > 0:
                cur = str(getattr(bg, "value_currency", "") or "USD").upper()
                return self._to_usd(va / 100.0, cur), "value"
        except Exception:
            pass
        # 2) resale floor in stars (what «Resale from X» shows). DIRECT field reads only —
        # do NOT call _get_gift_floor_stars here: it resolves+invokes a StarsController method
        # by reflection, and this runs on the UI thread (the live loop), which can ANR/crash.
        for nm in ("resell_min_stars", "min_resell_stars", "resellMinStars",
                   "floor_stars", "floorStars"):
            try:
                rms = int(getattr(bg, nm, 0) or 0)
            except Exception:
                rms = 0
            if rms > 0:
                return rms * self._STAR_USD, "floor"
        # 3) mint price × a collectible markup (weak fallback)
        try:
            st = int(getattr(bg, "stars", 0) or 0)
            if st > 0:
                return st * self._STAR_USD * 3.0, "mint"
        except Exception:
            pass
        return 0.0, ""

    def _auto_value_for(self, model, pattern, backdrop):
        """Auto collectible value in the selected currency, anchored on the gift's real market
        value with a gentle rarity / low-number nudge. '' when no market data + no override."""
        try:
            # the anchor is gift-level (doesn't change as the owner switches attributes) →
            # resolve it ONCE per constructor and cache, so the live loop stays cheap
            anchor_usd = getattr(self, "_ctor_anchor_usd", None)
            src = getattr(self, "_ctor_anchor_src", "")
            if anchor_usd is None:
                bg = getattr(self, "_pending_base_gift", None)
                anchor_usd, src = self._gift_value_anchor_usd(bg)
                self._ctor_anchor_usd = anchor_usd
                self._ctor_anchor_src = src
            if anchor_usd <= 0:
                return ""                                # unknown → leave blank, owner sets it
            # per-attribute weight: rarer → bigger. `neutral` is the rarity at which weight=1.
            def h(attr, neutral):
                if attr is None:
                    return 1.0
                p = self._attr_rarity(attr)
                if p <= 0:
                    p = neutral
                return (float(neutral) / max(min(p, 80.0), 0.15)) ** 0.25
            try:
                num = int(getattr(self, "_ctor_num", 1) or 1)
            except Exception:
                num = 1
            num = max(num, 1)
            if src == "value":
                # anchor = the gift's real shown «Ценность» (its rarity is already mostly baked
                # in). Normalize around a TYPICAL NFT attribute (~1%) so a typical copy ≈ the
                # real value, and let the chosen attributes swing it moderately — so the price
                # DOES change live as the owner picks model / backdrop / symbol, around the
                # realistic anchor instead of being pinned to it.
                prod = h(model, 1.0) * h(backdrop, 1.0) * h(pattern, 1.0)
                rar = max(0.8, min(prod ** 0.30, 1.6))
                nf = min(1.0 + 0.12 / (num ** 0.5), 1.15)
            else:
                # anchor = the FLOOR (cheapest, ~common copy) → full premium above it
                prod = h(model, 8.0) * h(backdrop, 8.0) * h(pattern, 8.0)
                rar = max(0.85, min(prod ** 0.55, 6.0))
                nf = min(1.0 + 0.30 / (num ** 0.5), 1.4)
            usd = anchor_usd * rar * nf
            cur = str(getattr(self, "_ctor_currency", "USD") or "USD").upper()
            try:
                self.log("[autoval] src=%s anchor$=%.0f rar=%.2f nf=%.2f -> $%.0f %s" % (
                    src, anchor_usd, rar, nf, usd, cur))
            except Exception:
                pass
            return self._round_value(self._from_usd(usd, cur), cur)
        except Exception:
            return ""

    def _round_value(self, v, cur):
        """Round a raw value to a clean, human-looking number per currency."""
        try:
            v = float(v)
        except Exception:
            return ""
        if v <= 0:
            return ""
        if cur == "RUB":
            step = 50 if v < 1000 else 100 if v < 10000 else 500 if v < 100000 else 1000
            return str(int(max(round(v / step) * step, step)))
        # USD / EUR
        if v < 20:
            r = round(v * 2) / 2.0                       # nearest 0.5
            return ("%.1f" % r).rstrip("0").rstrip(".")
        if v < 100:
            return str(int(round(v)))
        if v < 500:
            return str(int(round(v / 5) * 5))
        if v < 2000:
            return str(int(round(v / 10) * 10))
        return str(int(round(v / 50) * 50))

    def _refresh_auto_value(self):
        """One-shot: recompute + show the auto value from the sheet's current attributes,
        but only while in auto mode."""
        if not getattr(self, "_ctor_value_auto", False):
            return
        sheet = getattr(self, "_nat_sheet", None)
        if sheet is None:
            return
        try:
            m, p, b = self._read_sheet_attrs(sheet)
        except Exception:
            m = p = b = None
        amt = self._auto_value_for(m, p, b)
        if not amt:
            return
        self._ctor_value = amt
        pill = getattr(self, "_ctor_value_pill", None)
        if pill is not None:
            try:
                pill.setText(self._ctor_value_label())
            except Exception:
                pass

    def _start_autovalue_loop(self):
        """(Re)start the live auto-price loop. A generation token kills any prior loop so
        only one runs at a time (and so a stale loop can't outlive its sheet)."""
        try:
            self._ctor_value_loop_gen = getattr(self, "_ctor_value_loop_gen", 0) + 1
            gen = self._ctor_value_loop_gen
            run_on_ui_thread(lambda: self._ctor_autovalue_loop(gen, 0), 200)
        except Exception:
            pass

    def _ctor_autovalue_loop(self, gen, tick):
        try:
            # superseded by a newer loop / constructor, sheet gone, or manual override → stop
            if gen != getattr(self, "_ctor_value_loop_gen", 0):
                return
            if getattr(self, "_nat_sheet", None) is None or not getattr(self, "_ctor_value_auto", False):
                return
            if tick > 900:                               # ~5min backstop, never run forever
                return
            # the value pill detaching means the sheet was dismissed → stop cleanly. (Don't
            # stop before it's injected: pill is None for the first few ticks.)
            pill = getattr(self, "_ctor_value_pill", None)
            try:
                if pill is not None and hasattr(pill, "isAttachedToWindow") and not pill.isAttachedToWindow():
                    self._nat_sheet = None
                    return
            except Exception:
                pass
            self._refresh_auto_value()
        except Exception:
            pass
        # reschedule (snappy enough to feel live as the owner switches attributes)
        try:
            run_on_ui_thread(lambda: self._ctor_autovalue_loop(gen, tick + 1), 350)
        except Exception:
            pass

    def _show_constructor_grid(self, edit_gift, models, patterns, backdrops, base_gift_id=None):
        frag = get_last_fragment()
        ctx = frag.getParentActivity() if frag else None
        if not ctx:
            return
        bgid = base_gift_id or (int(edit_gift.get("base_gift_id") or 0) if edit_gift else 0)
        st = {"model": models[0] if models else None,
              "pattern": patterns[0] if patterns else None,
              "backdrop": backdrops[0] if backdrops else None,
              "tab": "model",
              "base_gift_id": bgid,
              "title": (edit_gift.get("title") if edit_gift else "Custom NFT"),
              "num": (edit_gift.get("num") if edit_gift else 1)}
        if edit_gift:
            for lst, key, ek in ((models, "model", "model"), (patterns, "pattern", "symbol"), (backdrops, "backdrop", "backdrop")):
                want = edit_gift.get(ek)
                for a in lst:
                    if self._attr_name(a) == want:
                        st[key] = a
                        break
        try:
            scroll = ScrollView(ctx)
            col = LinearLayout(ctx)
            col.setOrientation(LinearLayout.VERTICAL)
            p = AndroidUtilities.dp(12)
            col.setPadding(p, p, p, AndroidUtilities.dp(20))

            prev_wrap = FrameLayout(ctx)
            plp = LinearLayout.LayoutParams(AndroidUtilities.dp(140), AndroidUtilities.dp(140))
            plp.gravity = Gravity.CENTER_HORIZONTAL
            col.addView(prev_wrap, plp)

            ttl = TextView(ctx)
            ttl.setGravity(Gravity.CENTER)
            ttl.setText(str(st.get("title") or "Custom NFT"))
            ttl.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 19)
            ttl.setTextColor(Theme.getColor(Theme.key_dialogTextBlack))
            try: ttl.setTypeface(AndroidUtilities.bold())
            except Exception: pass
            tllp = LinearLayout.LayoutParams(-1, -2)
            tllp.topMargin = AndroidUtilities.dp(8)
            col.addView(ttl, tllp)

            sub = TextView(ctx)
            sub.setGravity(Gravity.CENTER)
            sub.setText("Случайные характеристики")
            sub.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 12)
            sub.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText))
            col.addView(sub, LinearLayout.LayoutParams(-1, -2))

            # current-attribute chips row (model / backdrop / pattern)
            chips_row = LinearLayout(ctx)
            chips_row.setOrientation(LinearLayout.HORIZONTAL)
            crlp = LinearLayout.LayoutParams(-1, -2)
            crlp.topMargin = AndroidUtilities.dp(12)
            col.addView(chips_row, crlp)

            def refresh_preview():
                try:
                    prev_wrap.removeAllViews()
                    self._render_attrs_into(ctx, prev_wrap, st["model"], st["pattern"], st["backdrop"])
                    chips_row.removeAllViews()
                    for a, lbl in ((st["model"], "модель"), (st["backdrop"], "фон"), (st["pattern"], "узор")):
                        chip = self._cur_chip(ctx, a, lbl)
                        chlp = LinearLayout.LayoutParams(0, -2, 1.0)
                        chlp.rightMargin = AndroidUtilities.dp(6)
                        chips_row.addView(chip, chlp)
                    prev_wrap.setAlpha(0.0); prev_wrap.setScaleX(0.90); prev_wrap.setScaleY(0.90)
                    pa = prev_wrap.animate().alpha(1.0).scaleX(1.0).scaleY(1.0).setDuration(240)
                    it = self._smooth_interp()
                    if it is not None: pa.setInterpolator(it)
                    pa.start()
                    self._stagger_children(chips_row, 20, 35, 5)
                except Exception:
                    pass

            # tabs
            tabs_row = LinearLayout(ctx)
            tabs_row.setOrientation(LinearLayout.HORIZONTAL)
            tlp = LinearLayout.LayoutParams(-1, -2)
            tlp.topMargin = AndroidUtilities.dp(12)
            tab_btns = {}

            grid_host = LinearLayout(ctx)
            grid_host.setOrientation(LinearLayout.VERTICAL)

            def build_grid():
                grid_host.removeAllViews()
                pool = {"model": models, "pattern": patterns, "backdrop": backdrops}[st["tab"]]
                rowv = None
                for i, a in enumerate(pool):
                    if i % 3 == 0:
                        rowv = LinearLayout(ctx)
                        rowv.setOrientation(LinearLayout.HORIZONTAL)
                        glp = LinearLayout.LayoutParams(-1, -2)
                        glp.topMargin = AndroidUtilities.dp(8)
                        grid_host.addView(rowv, glp)
                    cell = self._option_cell(ctx, st, a, lambda: (refresh_preview(), build_grid()))
                    celllp = LinearLayout.LayoutParams(0, -2, 1.0)
                    celllp.rightMargin = AndroidUtilities.dp(6) if (i % 3 != 2) else 0
                    rowv.addView(cell, celllp)

            def set_tab(t):
                if st.get("tab") == t:
                    return
                # Commit the tab SYNCHRONOUSLY. The guard above is the re-entrancy protection for
                # this whole path, and it used to read a value that `_swap_tab` only wrote 95 ms
                # later — so every tap inside that window sailed past it, including a double-tap on
                # the same tab. Two swaps then queued: the second called grid_host.removeAllViews()
                # while the first one's stagger animators were still running against those children,
                # and both started competing 190 ms alpha animations on grid_host. That is why fast
                # tapping «Модели»/«Фоны»/«Узоры» left cells stuck half-faded or the grid blank.
                st["tab"] = t
                st["tab_gen"] = int(st.get("tab_gen", 0)) + 1
                gen = st["tab_gen"]
                try:
                    grid_host.animate().cancel()
                    grid_host.animate().alpha(0.0).translationX(float(AndroidUtilities.dp(-8))).setDuration(90).start()
                except Exception:
                    pass
                def _swap_tab():
                    # Last tap wins: an older pending swap would rebuild the grid a second time and
                    # fight the newer fade-in.
                    if gen != int(st.get("tab_gen", 0)):
                        return
                    for k, b in tab_btns.items():
                        b.setBackground(self._ripple_bg(self._chip_bg(k == t), Theme.getColor(Theme.key_featuredStickers_addButton)))
                        try:
                            b.animate().scaleX(1.04 if k == t else 1.0).scaleY(1.04 if k == t else 1.0).setDuration(170).start()
                        except Exception:
                            pass
                    build_grid()
                    try:
                        grid_host.setTranslationX(float(AndroidUtilities.dp(8)))
                        grid_host.animate().alpha(1.0).translationX(0.0).setDuration(190).start()
                    except Exception:
                        pass
                    self._stagger_children(grid_host, 10, 28, 8)
                run_on_ui_thread(_swap_tab, 95)

            for key, label in (("model", "Модели"), ("backdrop", "Фоны"), ("pattern", "Узоры")):
                tb = TextView(ctx)
                tb.setText(label)
                tb.setGravity(Gravity.CENTER)
                tb.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 14)
                tb.setTextColor(Theme.getColor(Theme.key_dialogTextBlack))
                tb.setPadding(0, AndroidUtilities.dp(8), 0, AndroidUtilities.dp(8))
                tb.setBackground(self._ripple_bg(self._chip_bg(key == st["tab"]), Theme.getColor(Theme.key_featuredStickers_addButton)))
                tb.setOnClickListener(self._click(lambda v, k=key: set_tab(k), hap="swipe"))
                blp = LinearLayout.LayoutParams(0, -2, 1.0)
                blp.rightMargin = AndroidUtilities.dp(6)
                tabs_row.addView(tb, blp)
                tab_btns[key] = tb
            ghlp = LinearLayout.LayoutParams(-1, -2)
            ghlp.topMargin = AndroidUtilities.dp(8)
            col.addView(grid_host, ghlp)
            # tabs at the BOTTOM (like the production gift constructor)
            col.addView(tabs_row, tlp)

            save = self._pill(ctx, "Сохранить NFT", Theme.getColor(Theme.key_featuredStickers_addButton),
                              lambda v: self._ctor_save(st))
            svlp = LinearLayout.LayoutParams(-1, AndroidUtilities.dp(48))
            svlp.topMargin = AndroidUtilities.dp(16)
            col.addView(save, svlp)

            refresh_preview()
            build_grid()

            scroll.addView(col)
            b = BottomSheet.Builder(ctx)
            b.setCustomView(scroll)
            self._ctor_sheet = b.create()
            self._show_sheet_animated(self._ctor_sheet, scroll)
        except Exception as e:
            self._toast("конструктор: " + repr(e)[:140])

    def _option_cell(self, ctx, st, a, on_pick):
        cls = str(a.getClass().getSimpleName()).lower()
        kind = "model" if "model" in cls else ("backdrop" if "backdrop" in cls else "pattern")
        card = LinearLayout(ctx)
        card.setOrientation(LinearLayout.VERTICAL)
        card.setGravity(Gravity.CENTER_HORIZONTAL)
        sel = (a is st.get(kind))
        bg = GradientDrawable()
        bg.setCornerRadius(AndroidUtilities.dp(12))
        bg.setColor(self._cell_bg_color(sel))
        card.setBackground(self._ripple_bg(bg, Theme.getColor(Theme.key_featuredStickers_addButton)))
        try: card.setElevation(float(AndroidUtilities.dp(2 if sel else 0)))
        except Exception: pass
        card.setPadding(AndroidUtilities.dp(6), AndroidUtilities.dp(8), AndroidUtilities.dp(6), AndroidUtilities.dp(8))

        SZ = AndroidUtilities.dp(58)
        thumb = FrameLayout(ctx)
        # rounded tile background: for a model option show the FULL gift in that model
        # on the current backdrop (like the production «cat variants»); backdrop
        # option shows the color, pattern shows the symbol.
        bd = st.get("backdrop")
        if kind == "backdrop":
            self._fill_backdrop_oval(thumb, a)
        else:
            self._fill_backdrop_rect(thumb, bd)
        if kind == "model":
            self._add_doc(ctx, thumb, getattr(a, "document", None), AndroidUtilities.dp(50))
        elif kind == "pattern":
            self._add_doc(ctx, thumb, getattr(a, "document", None), AndroidUtilities.dp(40))

        # rarity badge top-right
        rb = TextView(ctx)
        rb.setText("%.1f%%" % self._attr_rarity(a))
        rb.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 9)
        rb.setTextColor(self._argb_signed(0xFFFFFF))
        rb.setPadding(AndroidUtilities.dp(5), AndroidUtilities.dp(1), AndroidUtilities.dp(5), AndroidUtilities.dp(1))
        rbg = GradientDrawable()
        rbg.setCornerRadius(AndroidUtilities.dp(8))
        rbg.setColor(0x66000000)  # semi-transparent black (positive 32-bit int)
        rb.setBackground(rbg)
        rblp = FrameLayout.LayoutParams(-2, -2, Gravity.RIGHT | Gravity.TOP)
        thumb.addView(rb, rblp)
        card.addView(thumb, LinearLayout.LayoutParams(SZ, SZ, Gravity.CENTER_HORIZONTAL))

        nm = TextView(ctx)
        nm.setText(self._attr_name(a))
        nm.setGravity(Gravity.CENTER)
        nm.setTextSize(TypedValue.COMPLEX_UNIT_DIP, 11)
        nm.setTextColor(Theme.getColor(Theme.key_dialogTextBlack))
        nm.setMaxLines(1)
        nlp = LinearLayout.LayoutParams(-1, -2)
        nlp.topMargin = AndroidUtilities.dp(5)
        card.addView(nm, nlp)

        def pick(v):
            st[kind] = a
            on_pick()
        card.setOnClickListener(self._click(pick))
        return card

    def _fill_backdrop_rect(self, wrap, backdrop_a):
        try:
            gd = GradientDrawable()
            gd.setCornerRadius(AndroidUtilities.dp(10))
            if backdrop_a is not None and jarray is not None:
                c = self._argb_signed(getattr(backdrop_a, "center_color", 0) or 0)
                e = self._argb_signed(getattr(backdrop_a, "edge_color", 0) or 0)
                gd.setGradientType(GradientDrawable.RADIAL_GRADIENT)
                gd.setGradientRadius(AndroidUtilities.dp(30))
                gd.setColors(jarray(jint)([c, e]))
            else:
                gd.setColor(Theme.getColor(Theme.key_windowBackgroundGray))
            wrap.setBackground(gd)
        except Exception:
            pass

    def _fill_backdrop_oval(self, wrap, backdrop_a):
        try:
            gd = GradientDrawable()
            gd.setShape(GradientDrawable.OVAL)
            if backdrop_a is not None and jarray is not None:
                c = self._argb_signed(getattr(backdrop_a, "center_color", 0) or 0)
                e = self._argb_signed(getattr(backdrop_a, "edge_color", 0) or 0)
                gd.setGradientType(GradientDrawable.RADIAL_GRADIENT)
                gd.setGradientRadius(AndroidUtilities.dp(28))
                gd.setColors(jarray(jint)([c, e]))
            else:
                gd.setColor(Theme.getColor(Theme.key_windowBackgroundGray))
            wrap.setBackground(gd)
        except Exception:
            pass

    def _add_doc(self, ctx, wrap, doc, size):
        try:
            if doc is None or BackupImageView is None or ImageLocation is None:
                return
            img = BackupImageView(ctx)
            loc = ImageLocation.getForDocument(doc)
            if loc is not None:
                img.setImage(loc, "%d_%d" % (size, size), None, 0, doc)
            try: img.startAnimation()
            except Exception: pass
            wrap.addView(img, FrameLayout.LayoutParams(size, size, Gravity.CENTER))
        except Exception:
            pass

    def _cell_bg_color(self, selected):
        if selected:
            base = Theme.getColor(Theme.key_featuredStickers_addButton) & 0xFFFFFF
            return 0x55000000 | base
        return Theme.getColor(Theme.key_windowBackgroundGray)

